type ComponentPropSetMap = FxHashMap<String, FxHashSet<String>>;

#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum AliasType {
    Prefix,
    Exact,
}

#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct AliasEntry {
    pub pattern: String,
    pub replacement: String,
    #[serde(rename = "type")]
    pub alias_type: AliasType,
}

/// The path aliases an `EngineOptions.pathAliasesJson` names: none for an
/// absent, blank or `null` value.
pub fn parse_path_aliases(json: Option<&str>) -> Result<Vec<AliasEntry>, String> {
    match json {
        None => Ok(Vec::new()),
        Some(s) if s.trim().is_empty() || s.trim() == "null" => Ok(Vec::new()),
        Some(s) => {
            #[derive(serde::Deserialize)]
            struct AliasWrapper {
                aliases: Vec<AliasEntry>,
            }
            serde_json::from_str::<AliasWrapper>(s)
                .map(|w| w.aliases)
                .map_err(|e| format!("EngineOptions.pathAliasesJson: invalid JSON — {e}"))
        }
    }
}

/// First alias that matches wins, so entry order is significant.
pub fn expand_alias(source: &str, aliases: &[AliasEntry]) -> Option<String> {
    for alias in aliases {
        match alias.alias_type {
            AliasType::Exact => {
                if source == alias.pattern {
                    return Some(alias.replacement.clone());
                }
            }
            AliasType::Prefix => {
                if source.starts_with(&alias.pattern) {
                    let rest = &source[alias.pattern.len()..];
                    return Some(format!("{}{}", alias.replacement, rest));
                }
            }
        }
    }
    None
}

/// Identity resolutions by file, then local, then whether a same-name
/// fallback applies: the components found and the fallback taken.
type IdentityMemo = FxHashMap<String, FxHashMap<String, [Option<(Vec<String>, Fallback)>; 2]>>;

/// Configuration and theme inputs, parsed once from EngineOptions JSON.
#[derive(Default)]
pub struct CssInputs {
    pub theme: FlatTheme,
    pub variable_map: VariableMap,
    pub contextual_vars: ContextualVarsMap,
    pub config: PropConfigMap,
    /// Each system prop's position in the system's config: the order the
    /// system defines its props in, which `config` does not keep.
    pub prop_order: FxHashMap<String, usize>,
    pub group_registry: FxHashMap<String, Vec<String>>,
    pub selector_aliases: SelectorAliasesMap,
    pub condition_aliases: ConditionAliasesMap,
    pub global_style_blocks: Option<Value>,
    pub keyframes_blocks: Option<Value>,
    /// Registered position-try collections, keyed and named as keyframes
    /// collections are: `{ exportName: { key: { name, descriptors } } }`.
    pub position_try_blocks: Option<Value>,
    /// Registered view-transition collections, keyed and named as
    /// keyframes collections are: `{ exportName: { key: { name, slots } } }`.
    pub view_transition_blocks: Option<Value>,
    pub package_map: FxHashMap<String, String>,
    pub path_aliases: Vec<AliasEntry>,
    pub static_css: Option<crate::forced_usage::StaticCssConfig>,
    /// Directory prefixes, relative to rootDir, of external packages.
    pub external_dirs: Vec<String>,
    pub analysis_context: AnalysisContext,
    /// The host's first candidate for each probe base, as the session
    /// gathered it at ingest; none where no session did.
    pub probe_evidence: Option<ProbeEvidence>,
    /// Each probe this analysis ended Incomplete: its importer, specifier,
    /// the candidate, and the spelling the host's filesystem opens.
    pub incomplete_probes: std::sync::Mutex<BTreeSet<IncompleteProbe>>,
    /// Probes whose host opens an opaque file before a later analysed
    /// candidate: resolved, but reported.
    pub shadowing_probes: std::sync::Mutex<BTreeSet<ShadowingProbe>>,
    /// The analysed modules this build's literal `import()`s name: what a
    /// declared closed site (`closedDynamicImports`) may load. Filled once,
    /// by the first reader with every module's loads.
    pub build_chunks: std::sync::OnceLock<Vec<String>>,
    /// The config-only modules ([`config_only`]), found once.
    pub config_only: std::sync::OnceLock<BTreeSet<String>>,
    /// What each analysed module imports or loads at runtime
    /// ([`runtime_imports`]), found once.
    pub runtime_imports: std::sync::OnceLock<BTreeMap<String, Vec<String>>>,
    /// This run's identity resolutions ([`resolve_identity`]). Each run
    /// starts empty: its files, links and evaluated components are its own.
    /// The key leaves those out, so every caller runs inside one
    /// `run_with_system_floor`, after `evaluated_ids` and `ids_by_binding`
    /// are final: a caller with a partial evaluated set would read stale
    /// answers.
    identity_memo: std::sync::Mutex<IdentityMemo>,
    /// This run's export lookups ([`import_identity`]), by module, then name.
    import_memo: std::sync::Mutex<FxHashMap<String, FxHashMap<String, ImportIds>>>,
    /// Each opening of an unread module, by the reason the safety relations
    /// record it under, for the diagnostic that names what it cost.
    pub(crate) unread_openings: std::sync::Mutex<BTreeMap<String, crate::link::UnreadOpening>>,
    /// `{ definitionKey: sourceText }` for the loaded system's configured
    /// transforms, keyed as its props' `transformId` (or, for a system that
    /// predates identities, their name).
    pub transform_sources: FxHashMap<String, String>,
    /// The loader's host-binding evidence for those sources.
    pub transform_provenance: crate::transforms::TransformProvenance,
    /// The theme's declaration scales, lowered once for system and
    /// component props alike.
    pub declaration_scales: DeclarationScales,
    pub dev_mode: bool,
    /// Production names components and utilities `{prefix}-{id}` and
    /// `{prefix}_{id}` (`ids::short_class_names`) under this prefix, which
    /// keeps two builds on one page apart; `None` keeps the readable names.
    pub short_class_prefix: Option<String>,
    /// Whether the analysis records what keeps each system slot open
    /// (`SlotProvenance`), which verbose output prints.
    pub slot_provenance: bool,
    /// Whether the transformed code's variant configs list their options.
    /// The official runtimes read only a variant's prop and default; a
    /// custom `runtimeImport` may read the list.
    pub variant_options: bool,
    /// The custom properties the theme registers with a numeric syntax,
    /// `<integer>` or `<number>`, with `--`: a number written to one needs
    /// no unit.
    pub numeric_properties: FxHashSet<String>,
    /// FNV-1a over each input that can change a component's declarations or
    /// runtime metadata, in canonical JSON: with the class prefix, the
    /// system's fingerprint. Global blocks, which emit outside component
    /// classes, take no part; keyframes take part by name only; the numeric
    /// registrations, which change only warnings and the slot's
    /// `declaredNumeric`, take none.
    pub system_hash: u64,
}

/// An optional engine option's JSON; empty or `null` is none.
fn parse_opt_value(name: &str, json: Option<&str>) -> Result<Option<Value>, String> {
    match json {
        None => Ok(None),
        Some(s) if s.trim().is_empty() || s.trim() == "null" => Ok(None),
        Some(s) => serde_json::from_str(s).map(Some).map_err(|e| format!("EngineOptions.{name}: invalid JSON — {e}")),
    }
}

/// `hash` continued with `json` in canonical form, then a separator; JSON
/// that does not parse continues as written.
fn fold_system_input(hash: u64, json: Option<&str>) -> u64 {
    let hash = match json.map(serde_json::from_str::<Value>) {
        Some(Ok(value)) => crate::ids::fnv1a_json(hash, &value),
        Some(Err(_)) => crate::ids::fnv1a(hash, json.unwrap_or_default()),
        None => hash,
    };
    crate::ids::fnv1a(hash, "\u{0}")
}

/// Each registered collection's export and key, and the name its CSS takes:
/// keyframes, position tries and view transitions are shaped alike.
pub(crate) fn registered_names(blocks: Option<&Value>) -> Vec<(&str, &str, Option<&str>)> {
    let collections = blocks.and_then(Value::as_object).into_iter().flatten();
    collections
        .flat_map(|(export, collection)| {
            collection.as_object().into_iter().flatten().map(move |(key, block)| {
                (export.as_str(), key.as_str(), block.get("name").and_then(Value::as_str))
            })
        })
        .collect()
}

/// What the host knows that the analysis cannot see.
#[derive(Debug, Default, Clone, serde::Deserialize)]
#[serde(rename_all = "camelCase", default)]
pub struct AnalysisContext {
    /// Sources ingestion skipped. Their renders are unseen, so while any is
    /// skipped nothing is pruned, and an error from an option kept only for
    /// that reason is a warning.
    pub skipped_sources: Vec<String>,
    /// The bundler leaves an `import(expr)` it cannot read unbundled (Vite,
    /// Rollup, Turbopack), so the load reaches no analysed module. Absent,
    /// it is read as webpack does: a context of the importer's directory.
    pub unbundled_computed_imports: bool,
    /// The analysed packages' directories, relative to rootDir: a load into
    /// one reaches only its modules.
    pub package_dirs: Vec<String>,
    /// Those of them whose package is linked rather than installed, spelled
    /// as their files are keyed: development names their files where they
    /// are defined, whatever the path spells.
    pub linked_dirs: Vec<String>,
    /// Those of them read from their package's compiled output: the package
    /// declares no source condition and ships no `src/`.
    pub output_dirs: Vec<String>,
    /// The host's extension order (spec §2.2 A2), as the session captured
    /// it; the built-in policy where no host resolves.
    pub extensions: Option<animus_system_loader::resolution::ExtensionPolicy>,
    /// Probes ingestion ended Incomplete (a Svelte resolver call whose
    /// import the host opens under another spelling, or opens as a file
    /// analysis never reads, spec §2.2 A8): each is an opening of this
    /// analysis, as one of its own probes is.
    pub openings: Vec<IngestionOpening>,
    /// Computed `import()`s the configuration declares closed
    /// (`closedDynamicImports`): each may load only what it names.
    pub closed_dynamic_imports: Vec<ClosedDynamicImport>,
    /// The build configuration files the host analysed, keyed as analysis
    /// keys them: config roots, beside the well-known tool config names.
    pub config_files: Vec<String>,
    /// The configured system file and every module its load read, keyed as
    /// analysis keys them, wherever they sit: known modules, whose import
    /// opens nothing, whether or not analysis reads them.
    pub system_modules: Vec<String>,
    /// The packages the app imports that have no dependency path to Animus,
    /// by name: their tags never match an Animus component by name.
    pub foreign_packages: Vec<String>,
    /// The faces the host preloads (its `fontPreloads` option: family
    /// names, or `{ family, weight?, style?, unicodeRange?, fetchpriority? }`),
    /// in place of each typed face's own `preload` flag; absent, the flags.
    pub font_preloads: Option<Vec<Value>>,
    /// The host publishes the prop-order file (`propOrderFile`): each
    /// component's authoring order and each file's tag table are built.
    pub prop_order: bool,
    /// The host's `exclude` list as the user wrote it, or the defaults it
    /// replaces: a remedy that excludes a file names it in full. Diagnostics
    /// only.
    pub exclude: Option<Vec<String>>,
}

/// Whether the probe base or candidate `path` names one of the system's
/// modules: exactly, by its extension dropped, or as a directory's index.
pub(crate) fn is_system_module(path: &str, inputs: &CssInputs) -> bool {
    inputs.analysis_context.system_modules.iter().any(|module| {
        module == path
            || module.rsplit_once('.').is_some_and(|(stem, _)| stem == path)
            || module.strip_prefix(path).is_some_and(|rest| rest.starts_with("/index."))
    })
}

/// A computed `import()` declared closed: written in `importer` (keyed as
/// the analysis keys it), inside the function named `enclosing_function`,
/// loading only `targets`. A caller's assertion the analysis records, not
/// one it proves.
#[derive(Debug, Clone, PartialEq, Eq, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ClosedDynamicImport {
    pub importer: String,
    pub enclosing_function: String,
    pub targets: ClosedTargets,
}

/// What a declared closed `import()` may load.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum ClosedTargets {
    /// The chunks the build's own literal `import()`s produce: the modules
    /// they name.
    BuildChunks,
}

/// One computed load's expansion under the host's own semantics: every
/// file it may load, with how the analysis reads each, and whether the
/// host could list them all.
#[derive(Debug, Clone, PartialEq, Eq, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct HostExpansion {
    /// The importing module, as the analysis keys it.
    pub importer: String,
    /// The load's byte offset in the importer.
    pub start: u32,
    /// Whether `files` is every file the load may load.
    pub closed: bool,
    pub files: Vec<ExpandedFile>,
}

#[derive(Debug, Clone, PartialEq, Eq, serde::Deserialize)]
pub struct ExpandedFile {
    pub path: String,
    pub status: ExpandedStatus,
}

/// How the analysis reads a file an expansion may load.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum ExpandedStatus {
    /// A module the analysis holds.
    Analysed,
    /// A file the host loads as an opaque value (spec §2.2 A8).
    Opaque,
    /// A file the analysis does not read.
    Unanalysed,
}

/// Why ingestion ended a probe Incomplete.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum IngestionOpeningKind {
    CaseMismatch,
    Skipped,
}

/// A probe ingestion ended Incomplete.
#[derive(Debug, Clone, PartialEq, Eq, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct IngestionOpening {
    pub importer: String,
    pub specifier: String,
    pub candidate: String,
    pub opened: String,
    pub why: IngestionOpeningKind,
    /// The analysed candidate a fall-through would have read.
    #[serde(default)]
    pub later: Option<String>,
}

impl CssInputs {
    #[allow(clippy::too_many_arguments)]
    pub fn from_json(
        theme_json: Option<&str>,
        variable_map_json: Option<&str>,
        contextual_vars_json: Option<&str>,
        config_json: Option<&str>,
        group_registry_json: Option<&str>,
        selector_aliases_json: Option<&str>,
        condition_aliases_json: Option<&str>,
        global_style_blocks_json: Option<&str>,
        keyframes_json: Option<&str>,
        package_resolution_json: Option<&str>,
        path_aliases_json: Option<&str>,
        static_css_json: Option<&str>,
        external_dirs_json: Option<&str>,
        dev_mode: bool,
    ) -> Result<Self, String> {
        fn parse<T: serde::de::DeserializeOwned + Default>(
            name: &str,
            json: Option<&str>,
        ) -> Result<T, String> {
            match json {
                None => Ok(T::default()),
                Some(s) if s.trim().is_empty() || s.trim() == "null" => Ok(T::default()),
                Some(s) => serde_json::from_str(s)
                    .map_err(|e| format!("EngineOptions.{name}: invalid JSON — {e}")),
            }
        }
        let path_aliases = parse_path_aliases(path_aliases_json)?;
        let static_css = match static_css_json {
            None => None,
            Some(s) if s.trim().is_empty() || s.trim() == "null" => None,
            Some(s) => {
                let parsed = crate::forced_usage::StaticCssConfig::parse(s)
                    .map_err(|e| format!("EngineOptions.staticCssJson: {e}"))?;
                if parsed.is_empty() {
                    None
                } else {
                    Some(parsed)
                }
            }
        };
        let keyframes_blocks = parse_opt_value("keyframesJson", keyframes_json)?;
        let system_hash = [
            config_json,
            group_registry_json,
            theme_json,
            variable_map_json,
            contextual_vars_json,
            selector_aliases_json,
            condition_aliases_json,
        ]
        .into_iter()
        .fold(crate::ids::FNV_OFFSET, fold_system_input);
        let system_hash = crate::ids::fnv1a_json(system_hash, &registered_names(keyframes_blocks.as_ref()));
        let mut config = parse("configJson", config_json)?;
        crate::theme::key_unidentified_transforms(&mut config);
        let prop_order = parse::<serde_json::Map<String, Value>>("configJson", config_json)?
            .keys()
            .enumerate()
            .map(|(position, prop)| (prop.clone(), position))
            .collect();
        Ok(CssInputs {
            theme: parse("themeJson", theme_json)?,
            variable_map: parse("variableMapJson", variable_map_json)?,
            contextual_vars: parse("contextualVarsJson", contextual_vars_json)?,
            config,
            prop_order,
            group_registry: parse("groupRegistryJson", group_registry_json)?,
            selector_aliases: parse("selectorAliasesJson", selector_aliases_json)?,
            condition_aliases: parse("conditionAliasesJson", condition_aliases_json)?,
            global_style_blocks: parse_opt_value(
                "globalStyleBlocksJson",
                global_style_blocks_json,
            )?,
            keyframes_blocks,
            position_try_blocks: None,
            view_transition_blocks: None,
            package_map: parse("packageResolutionJson", package_resolution_json)?,
            path_aliases,
            static_css,
            transform_sources: FxHashMap::default(),
            transform_provenance: Default::default(),
            declaration_scales: DeclarationScales::default(),
            external_dirs: parse("externalDirsJson", external_dirs_json)?,
            analysis_context: AnalysisContext::default(),
            probe_evidence: None,
            incomplete_probes: Default::default(),
            shadowing_probes: Default::default(),
            build_chunks: Default::default(),
            config_only: Default::default(),
            runtime_imports: Default::default(),
            identity_memo: Default::default(),
            import_memo: Default::default(),
            unread_openings: Default::default(),
            dev_mode,
            short_class_prefix: None,
            slot_provenance: false,
            variant_options: false,
            numeric_properties: FxHashSet::default(),
            system_hash,
        })
    }

    /// Names production classes short under `prefix`: a letter, then
    /// letters and digits, so the first `-` or `_` of a name ends it.
    pub fn set_short_class_prefix(&mut self, prefix: Option<&str>) -> Result<(), String> {
        let Some(prefix) = prefix else { return Ok(()) };
        if !crate::css::is_plain_name(prefix) {
            return Err(format!(
                "EngineOptions.shortClassPrefix: '{prefix}' is not a letter followed by letters and digits"
            ));
        }
        self.short_class_prefix = Some(prefix.to_string());
        Ok(())
    }

    /// The prefix production names classes short under, if any.
    pub(crate) fn short_classes(&self) -> Option<&str> {
        self.short_class_prefix.as_deref().filter(|_| !self.dev_mode)
    }

    /// Reads the theme's property records for the custom properties it
    /// registers with a numeric syntax. Only a theme with one folds them
    /// into the system's fingerprint.
    pub fn set_property_records(&mut self, json: Option<&str>) -> Result<(), String> {
        #[derive(serde::Deserialize)]
        struct PropertyRecord {
            name: String,
            syntax: Option<String>,
            registered: bool,
        }
        let Some(json) = json.map(str::trim).filter(|s| !s.is_empty() && *s != "null") else {
            return Ok(());
        };
        let records: Vec<PropertyRecord> =
            serde_json::from_str(json).map_err(|e| format!("EngineOptions.propertyRecordsJson: {e}"))?;
        // Beside the system hash, not in it: the set changes only warnings
        // and runtime metadata, never a class name or a declaration.
        self.numeric_properties = records
            .into_iter()
            .filter(|record| {
                record.registered && matches!(record.syntax.as_deref().map(str::trim), Some("<integer>" | "<number>"))
            })
            .map(|record| format!("--{}", record.name))
            .collect();
        Ok(())
    }

    /// Binds the configuration's declaration props to the theme's declaration
    /// scales; a registration that cannot bind fails the whole analysis.
    pub fn bind_declarations(&mut self, json: Option<&str>) -> Result<(), String> {
        self.declaration_scales =
            crate::declarations::bind_declaration_props(&mut self.config, json, &self.theme)?;
        self.system_hash = fold_system_input(self.system_hash, json);
        Ok(())
    }

    /// The system's fingerprint under a class prefix.
    pub fn system_fingerprint(&self, class_prefix: &str) -> String {
        crate::ids::fingerprint(crate::ids::fnv1a(self.system_hash, class_prefix))
    }

    /// The registered position tries and view transitions, from their
    /// engine options; their names take part in the system hash, as keyframe
    /// names do.
    pub fn set_registered_collections(
        &mut self,
        position_tries: Option<&str>,
        view_transitions: Option<&str>,
    ) -> Result<(), String> {
        self.position_try_blocks = self.registered_collection("positionTryJson", position_tries)?;
        self.view_transition_blocks = self.registered_collection("viewTransitionsJson", view_transitions)?;
        Ok(())
    }

    /// One registered collection's option, its names folded into the hash
    /// when it holds any: a system without one keeps its fingerprint.
    fn registered_collection(&mut self, option: &str, json: Option<&str>) -> Result<Option<Value>, String> {
        let blocks = parse_opt_value(option, json)?;
        if blocks.is_some() {
            self.system_hash = crate::ids::fnv1a_json(self.system_hash, &registered_names(blocks.as_ref()));
        }
        Ok(blocks)
    }

    /// Merges the prefix's generated names into the authored-name map.
    pub fn set_generated_names(&mut self, json: Option<&str>) -> Result<(), String> {
        let Some(json) = json.map(str::trim).filter(|s| !s.is_empty() && *s != "null") else {
            return Ok(());
        };
        let generated: FxHashMap<String, String> =
            serde_json::from_str(json).map_err(|e| format!("EngineOptions.generatedNamesJson: {e}"))?;
        self.contextual_vars.add_generated(generated);
        self.system_hash = fold_system_input(self.system_hash, Some(json));
        Ok(())
    }

    pub fn set_transform_sources(&mut self, json: Option<&str>) -> Result<(), String> {
        self.transform_sources = match json {
            None => FxHashMap::default(),
            Some(s) if s.trim().is_empty() || s.trim() == "null" => FxHashMap::default(),
            Some(s) => serde_json::from_str(s)
                .map_err(|e| format!("EngineOptions.transformSourcesJson: invalid JSON — {e}"))?,
        };
        self.system_hash = fold_system_input(self.system_hash, json);
        Ok(())
    }

    pub fn set_transform_provenance(&mut self, json: Option<&str>) {
        self.transform_provenance = crate::transforms::TransformProvenance::from_json(json);
        self.system_hash = fold_system_input(self.system_hash, json);
    }
}

/// Manifest component entry; field names are the plugin-consumed wire shape.
#[derive(Debug, Clone, serde::Serialize)]
pub struct ComponentDescriptor {
    pub file: String,
    pub binding: String,
    pub class_name: String,
    pub extends_from: Option<String>,
    pub terminal: String,
    pub tag: String,
    pub replacement: String,
    pub system_prop_names: Vec<String>,
    /// The component's definition fingerprint, which its location takes no
    /// part in.
    pub definition_fingerprint: String,
    /// The props it accepts in authoring order: its variant props, its
    /// states, its system props in the order their rules apply
    /// (`authoring_rank`), then its custom props in declaration order. Built
    /// only for a host that publishes the prop-order file.
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub authoring_order: Vec<OrderedProp>,
}

#[derive(Debug, Clone, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct CssDiagnostic {
    pub file: String,
    pub component: String,
    pub kind: String,
    pub message: String,
    /// Theme token path (`scale.key`); set only by the external-token walk.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub token: Option<String>,
    /// Stable diagnostic code, `animus.<namespace>.<slug>`.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub code: Option<String>,
    /// `"error"` fails strict builds in the plugin; `"warn"` does not.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub severity: Option<String>,
    /// 1-based line and column of the dropped or degraded input, or of the
    /// declaration it belongs to; absent where the input has no source
    /// location (the loaded system, `staticCss`). A line can come alone.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub line: Option<u32>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub column: Option<u32>,
    /// The dropped key or expression as written, cut to
    /// `DROPPED_TEXT_LIMIT` characters; a wholly dropped declaration is named
    /// by `component` instead.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub dropped: Option<String>,
    /// Byte offset of the location in `file`, until the engine, which holds
    /// the source, turns it into `line` and `column`.
    #[serde(skip)]
    pub(crate) offset: Option<u32>,
}

/// The longest `dropped` text a diagnostic carries, in characters.
const DROPPED_TEXT_LIMIT: usize = 120;

impl CssDiagnostic {
    /// Located at byte `offset` of its file.
    pub(crate) fn at(mut self, offset: u32) -> Self {
        self.offset = Some(offset);
        self
    }

    /// Located on `line` of its file, where nothing finer is known.
    pub(crate) fn on_line(mut self, line: usize) -> Self {
        self.line = u32::try_from(line).ok();
        self
    }

    /// The column on that line, in characters.
    pub(crate) fn with_column(mut self, column: usize) -> Self {
        self.column = u32::try_from(column).ok();
        self
    }

    /// What was dropped, as written.
    pub(crate) fn dropping(mut self, text: &str) -> Self {
        self.dropped = Some(match text.char_indices().nth(DROPPED_TEXT_LIMIT) {
            Some(_) => {
                let end = text.char_indices().nth(DROPPED_TEXT_LIMIT - 1).map_or(text.len(), |(at, _)| at);
                format!("{}…", &text[..end])
            }
            None => text.to_string(),
        });
        self
    }

    /// Turns a byte offset into `source`, the diagnostic's file, into a
    /// 1-based line and a column counted in characters.
    pub fn locate(&mut self, source: &str) {
        let Some(offset) = self.offset.take() else { return };
        let Some(before) = source.get(..(offset as usize).min(source.len())) else { return };
        let line = before.matches('\n').count() + 1;
        let column = before.rsplit('\n').next().map_or(0, |text| text.chars().count()) + 1;
        self.line = u32::try_from(line).ok();
        self.column = u32::try_from(column).ok();
    }
}

pub(crate) fn diagnostic_code_from_message(message: &str) -> Option<String> {
    let start = message.rfind("(animus.")?;
    let rest = &message[start + 1..];
    let end = rest.find(')')?;
    let code = &rest[..end];
    code.chars()
        .all(|c| c.is_ascii_alphanumeric() || c == '.' || c == '-')
        .then(|| code.to_string())
}

/// A skip's message less the code its reason named, and that code: the last
/// `(animus.…)` it names, wherever the reason put it (a const-held skip
/// names its const after it). The record prints its code itself, so its
/// message drops that occurrence and keeps every other word.
fn split_code(message: &str) -> (String, Option<String>) {
    let Some(code) = diagnostic_code_from_message(message) else {
        return (message.to_string(), None);
    };
    let named = format!(" ({code})");
    let message = match message.rfind(&named) {
        Some(at) => format!("{}{}", &message[..at], &message[at + named.len()..]),
        None => message.to_string(),
    };
    (message, Some(code))
}

const COMPOSE_UNRESOLVABLE_SLOT: &str = "animus.compose.unresolvable-slot";

/// Source-proven unsupported Animus declarations. Each code is `error`
/// severity: a warning by default, fatal only under explicit strictness.
const UNSUPPORTED_MEMBER_PARENT: &str = "animus.extension.unsupported-member-parent";
/// Components whose extensions extraction cannot order: a cycle, or a chain
/// through a binding its module declares by more than one chain.
const EXTENSION_CYCLE: &str = "animus.extension.cycle";
const UNSUPPORTED_EXTEND_ARGUMENTS: &str = "animus.extension.unsupported-arguments";
const UNSUPPORTED_VARIANT_CONFIG_REFERENCE: &str = "animus.variant.unsupported-config-reference";
const STAGE_EVALUATION_FAILED: &str = "animus.chain.stage-evaluation-failed";
const UNSUPPORTED_CHAIN_METHOD: &str = "animus.chain.unsupported-method";
const UNSUPPORTED_TERMINAL_TARGET: &str = "animus.chain.unsupported-terminal-target";
const UNSUPPORTED_TRANSFORM_REFERENCE: &str = "animus.props.unsupported-transform-reference";
const UNSUPPORTED_PROPS_CONFIG: &str = "animus.props.unsupported-config";
const UNSUPPORTED_DEFAULT_EXPORT: &str = "animus.chain.unsupported-default-export";
const UNSUPPORTED_NAMESPACE_ROOT: &str = "animus.chain.unsupported-namespace-root";
/// An error: a chain written as an object-literal property is never
/// extracted, so its component renders without its styles.
const UNSUPPORTED_OBJECT_MEMBER: &str = "animus.chain.unsupported-object-member";
/// An error: the same root reached through a barrel's local export of an
/// import, which went unreported before the resolver followed it.
const NAMESPACE_ROOT_THROUGH_BARREL: &str = "animus.chain.namespace-root-through-barrel";
/// A configured transform rejected before registration loses its meaning
/// the same way, so it shares the optional-strict policy.
const CONFIGURED_TRANSFORM_REJECTED: &str = "animus.transform.configured-rejected";
/// A value missing from a strict, populated scale is omitted rather than
/// applied raw; the author meant a token the scale does not have.
const STRICT_TOKEN_MISS: &str = "animus.props.strict-token-miss";
/// A strict-scale miss or an unresolvable token alias at a render whose tag
/// matches an Animus component by name alone: it may render another
/// library's component, so the finding is a warning.
const POSSIBLE_SYSTEM_PROP_MISS: &str = "animus.usage.possible-system-prop-miss";
/// A configured transform that exhausts its evaluation budget or reads the
/// host where no runtime slot exists (style blocks, variants, states,
/// global styles): its declaration falls back to the raw value.
const STATIC_EVALUATION_UNAVAILABLE: &str = "animus.transform.static-evaluation-unavailable";

/// An error: a binding names a key the sealed transform registry lacks
/// (spec §7.4 D10), an internal invariant failure; nothing is evaluated.
const TRANSFORM_UNSEALED_BINDING: &str = "animus.transform.unsealed-binding";
/// An error: a chain built inside a function or render, or a builder a
/// later declaration completes, is never extracted, so its styles reach no
/// stylesheet and the system builder stays in the bundle. A host that
/// builds at runtime on purpose sets the code's level in `diagnostics`.
const RUNTIME_BUILDER_REFERENCE: &str = "animus.extract.runtime-builder-reference";
/// Retired: never emitted. A value a render routes to an extracted component
/// through a declaration usage attribution misses now takes that
/// component's static class (`RoutedValue`). Kept in the code table so
/// configuration naming it stays valid.
const UNATTRIBUTED_SYSTEM_PROPS: &str = "animus.usage.unattributed-system-props";
/// A warning, never escalated: props a `cloneElement` call passes to an
/// element usage cannot name, from a value it cannot list, are not tracked,
/// so options only they set can be pruned.
const UNTRACKED_CLONE_PROPS: &str = "animus.usage.untracked-clone-props";
/// A warning, never escalated: a `createElement` call on an extracted
/// component passes props extraction cannot read (a value, a spread or a
/// computed key), so their system props take no static class; the runtime
/// slot still applies them.
const UNREAD_CREATE_ELEMENT_PROPS: &str = "animus.usage.unread-create-element-props";
/// A warning: one runtime module load opens more components than
/// `WIDE_MODULE_LOAD_LIMIT`, so the user can see why pruning stopped.
const WIDE_MODULE_LOAD: &str = "animus.usage.wide-module-load";
/// A probe the host's first candidate ends under another spelling (spec
/// §2.2 A8, Incomplete(CaseMismatch)): a case- or normalization-insensitive
/// host opens a file analysis never reads, so nothing is pruned.
const RESOLVE_CASE_MISMATCH: &str = "animus.resolve.case-mismatch";
/// A probe the host ends at a file analysis never reads, where analysis
/// would otherwise have read a later candidate (spec §2.2 A8,
/// Incomplete(SkippedSource)).
const RESOLVE_SKIPPED_SOURCE: &str = "animus.resolve.skipped-source";
/// Any other probe the host ends at a file analysis never reads (spec §2.2
/// A8): no opening stops pruning silently.
const RESOLVE_UNANALYSED_IMPORT: &str = "animus.resolve.unanalysed-import";
/// A computed `import()` the configuration declares closed
/// (`closedDynamicImports`): the assumption the analysis takes, recorded.
const LOAD_DECLARED_CLOSED: &str = "animus.load.declared-closed";
/// A `closedDynamicImports` entry that names no computed `import()`.
const LOAD_DECLARED_CLOSED_UNMATCHED: &str = "animus.load.declared-closed-unmatched";
/// A warning, once per opening: a module reaches a package the analysis
/// does not read, which may change exported objects, so declarations that
/// read them are not extracted. It names the declarations and the exclusion
