    #[test]
    fn unresolvable_alias_declaration_dropped_with_warn_diagnostic() {
        let out = analyze(
            &[(
                "a.tsx",
                "export const Broken = ds.styles({ display: 'flex', border: '1px solid {colors.missing}', '&:hover': { outline: '2px solid {colors.gone.999}' } }).asElement('div');\nexport const App = () => <Broken />;\n",
            )],
            &test_inputs(),
        );
        assert!(!out.css.contains("{colors.missing}"), "{}", out.css);
        assert!(!out.css.contains("{colors.gone.999}"), "{}", out.css);
        // Sibling static declaration survives the shed.
        assert!(
            out.sheets.base.contains("display: flex"),
            "{}",
            out.sheets.base
        );
        let warns = diagnostics_of(&out, "warn");
        assert_eq!(warns.len(), 2, "{:?}", out.diagnostics);
        assert!(
            warns.iter().any(|d| d.file == "a.tsx"
                && d.component == "Broken"
                && d.message.contains("{colors.missing}")
                && d.message.contains("'border'")),
            "{:?}",
            out.diagnostics
        );
        assert!(
            warns.iter().any(|d| d.component == "Broken"
                && d.message.contains("{colors.gone.999}")
                && d.message.contains("'outline'")),
            "{:?}",
            out.diagnostics
        );
    }

    /// Scale entries on two exemption-list properties keep the exemption
    /// assertions from being vacuous.
    fn token_shape_inputs() -> CssInputs {
        let mut inputs = CssInputs::from_json(
            None,
            None,
            None,
            Some(
                r#"{"bg": {"property": "backgroundColor", "scale": "colors"},
                    "fontFamily": {"property": "fontFamily", "scale": "fonts"},
                    "gridArea": {"property": "gridArea", "scale": "space"},
                    "display": {"property": "display"}}"#,
            ),
            Some(r#"{"color": ["bg"]}"#),
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            false,
        )
        .unwrap();
        inputs
            .theme
            .insert("colors.primary".into(), "#ff2800".into());
        inputs
    }

    #[test]
    fn token_shaped_value_warns_but_is_emitted_as_authored() {
        let out = analyze(
            &[(
                "a.tsx",
                "export const Typo = ds.styles({ display: 'flex', bg: 'accent.solid' }).asElement('div');\nexport const App = () => <Typo />;\n",
            )],
            &token_shape_inputs(),
        );
        assert!(
            out.sheets.base.contains("background-color: accent.solid"),
            "{}",
            out.sheets.base
        );
        assert!(
            out.sheets.base.contains("display: flex"),
            "{}",
            out.sheets.base
        );
        let warns = diagnostics_of(&out, "warn");
        assert_eq!(warns.len(), 1, "{:?}", out.diagnostics);
        let w = warns[0];
        assert_eq!(w.file, "a.tsx");
        assert_eq!(w.component, "Typo");
        assert!(w.message.contains("accent.solid"), "{}", w.message);
        assert!(w.message.contains("'background-color'"), "{}", w.message);
        assert!(
            w.message.contains("check the key against the theme"),
            "{}",
            w.message
        );
        assert!(w.message.contains("emitted as authored"), "{}", w.message);
    }

    fn external_dir_inputs() -> CssInputs {
        let mut inputs = token_shape_inputs();
        inputs.external_dirs = vec!["kit/src".into()];
        inputs
    }

    /// Space props on `padding-left` only through `pl`; `t-spacing-1` is a
    /// contextual variable of the space scale, and `md` a key of both space
    /// and breakpoints.
    fn kit_spacing_inputs() -> CssInputs {
        let mut inputs = CssInputs::from_json(
            None,
            None,
            Some(r#"{"space": ["t-spacing-1"]}"#),
            Some(r#"{"pl": {"property": "paddingLeft", "scale": "space"}}"#),
            Some(r#"{"space": ["pl"]}"#),
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            Some(r#"["kit/src"]"#),
            false,
        )
        .unwrap();
        inputs.theme.insert("space.1".into(), "4px".into());
        inputs.theme.insert("space.md".into(), "var(--space-md)".into());
        inputs.theme.insert("breakpoints.md".into(), "960".into());
        inputs
    }

    #[test]
    fn token_names_in_an_included_package_report_as_in_its_own_build() {
        let source = "export const chipContent = ds.styles({ paddingLeft: 't-spacing-1', scrollPaddingLeft: 't-spacing-1' }).asClass();\n";
        // Every diagnostic for the file, by code and first clause.
        let reported = |path: &str, source: &str| {
            let out = analyze(&[(path, source)], &kit_spacing_inputs());
            let mut all: Vec<_> = out
                .diagnostics
                .iter()
                .map(|d| (d.code.clone(), d.message.split(" — ").next().unwrap_or_default().to_string()))
                .collect();
            all.sort();
            all
        };
        let own = reported("src/Chip.tsx", source);
        assert_eq!(own.len(), 2, "both longhands name a token: {own:?}");
        assert!(own.iter().all(|(code, _)| code.as_deref() == Some(TOKEN_SHAPED_VALUE)), "{own:?}");
        assert_eq!(reported("kit/src/Chip.tsx", source), own, "a consuming app reports what the kit's build does, once");
        // A name the consumer does not know stays an external candidate alone.
        let unknown = reported("kit/src/Chip.tsx", "export const chipContent = ds.styles({ paddingLeft: 'unseen' }).asClass();\n");
        assert!(matches!(unknown.as_slice(), [(Some(code), _)] if code == EXTERNAL_TOKEN_CANDIDATE), "{unknown:?}");
    }

    #[test]
    fn unowned_token_hints_name_every_scale_with_the_key_fitting_first() {
        let out = analyze(&[("src/a.tsx", "export const a = ds.styles({ scrollPaddingInline: 'md' }).asClass();\n")], &kit_spacing_inputs());
        let warned: Vec<_> = out.diagnostics.iter().filter(|d| d.code.as_deref() == Some(TOKEN_SHAPED_VALUE)).collect();
        assert_eq!(warned.len(), 1, "{:?}", out.diagnostics);
        let message = &warned[0].message;
        assert!(message.contains("'space.md'") && message.contains("'breakpoints.md'"), "{message}");
        assert!(message.contains("write '{space.md}'"), "{message}");
    }

