    /// Contract: every system slot the floor keeps names each owner that
    /// keeps it, and the rule or site that keeps that owner open.
    #[test]
    fn each_kept_slot_names_what_keeps_it_open() {
        let source = "export const Box = ds.system({ space: true }).asElement('div');\n\
                      const Card = ds.system({ space: true }).asElement('div');\n\
                      export const App = ({ n, rest }) => <><Box p={n} /><Card {...rest} /></>;\n";
        let mut inputs = test_inputs();
        assert!(analyze(&[("a.tsx", source)], &inputs).slot_provenance.is_none());
        inputs.slot_provenance = true;
        let provenance = analyze(&[("a.tsx", source)], &inputs).slot_provenance.unwrap();
        assert!(provenance.usage.is_empty(), "{:?}", provenance.usage);
        assert_eq!(provenance.props.keys().collect::<Vec<_>>(), ["m", "p"]);
        let keeper = |prop: &str, owner: &str| {
            provenance.props[prop].iter().find(|keeper| keeper.owner == owner).map(|keeper| keeper.opening.rule)
        };
        assert_eq!(keeper("p", "a.tsx::Box"), Some("runtime-value"));
        let site = provenance.props["p"].iter().find(|keeper| keeper.owner == "a.tsx::Box").unwrap();
        assert_eq!((site.opening.file.as_deref(), site.opening.at.is_some()), (Some("a.tsx"), true));
        assert_eq!(keeper("p", "a.tsx::Card"), Some("unproven-owner"));
        assert_eq!(keeper("m", "a.tsx::Box"), None, "a value no use writes keeps no slot");
        assert_eq!(keeper("m", "a.tsx::Card"), Some("unproven-owner"));
        assert_eq!(provenance.owners["a.tsx::Card"][0].rule, "spread");
        // An unseen source leaves usage unproven project-wide.
        inputs.analysis_context.skipped_sources = vec!["unseen.tsx".into()];
        let unproven = analyze(&[("a.tsx", source)], &inputs).slot_provenance.unwrap();
        assert_eq!(unproven.usage, [SlotOpening::rule("skipped-source").in_file("unseen.tsx")]);
        assert_eq!(unproven.owners["a.tsx::Box"].iter().map(|reason| reason.rule).collect::<Vec<_>>(), ["not-module-confined"]);
    }

    #[test]
    fn total_floor_empty_project_has_no_slots() {
        let out = analyze(&[], &test_inputs());
        assert!(out.dynamic_props.is_empty());
        assert!(
            !out.sheets.system.contains("-dyn-"),
            "{}",
            out.sheets.system
        );
    }

    #[test]
    fn total_floor_static_invariance() {
        let source = "export const Box = ds.system({ space: true }).asElement('div');\nexport const App = () => <Box p={8} />;\n";
        // An unseen source leaves usage unproven, so the floor holds.
        let mut inputs = test_inputs();
        inputs.analysis_context.skipped_sources = vec!["unseen.tsx".into()];
        let legacy = analyze_with_total_system_floor(&[("a.tsx", source)], &inputs, false);
        let floor = analyze_with_total_system_floor(&[("a.tsx", source)], &inputs, true);

        assert_eq!(floor.system_prop_map, legacy.system_prop_map);
        assert_eq!(
            floor.system_prop_map["p"]["8"],
            legacy.system_prop_map["p"]["8"]
        );
        assert!(legacy.dynamic_props.is_empty());
        assert!(floor.dynamic_props.contains_key("p"));
    }

    #[test]
    fn enrichment_static_invariance() {
        let source = "export const Box = ds.system({ space: true }).asElement('div');\nexport const App = () => <Box p={8} />;\n";
        let counter = ParseCounter::new(0);
        let ast = OwnedAst::parse("a.tsx".to_string(), source.to_string(), &counter);
        let enriched = extract_file_facts_with_prefix(&ast, "animus");
        let mut legacy = enriched.clone();
        legacy.usage = crate::usage_facts::collect_usage_facts(ast.program());
        legacy.usage_enriched = None;

        let order = vec!["a.tsx".to_string()];
        let enriched_out = run(
            &BTreeMap::from([("a.tsx".to_string(), enriched)]),
            &order,
            &test_inputs(),
            "animus",
        );
        let legacy_out = run(
            &BTreeMap::from([("a.tsx".to_string(), legacy)]),
            &order,
            &test_inputs(),
            "animus",
        );

        assert_eq!(enriched_out.system_prop_map, legacy_out.system_prop_map);
        assert_eq!(enriched_out.css, legacy_out.css);
    }

    #[test]
    fn total_floor_keeps_custom_props_detection_gated_and_component_qualified() {
        let static_only = analyze(
            &[(
                "a.tsx",
                "export const Card = ds.props({ size: { property: 'flexBasis' } }).asElement('div');\nexport const App = () => <Card size=\"sm\" />;\n",
            )],
            &test_inputs(),
        );
        let static_card = static_only.components.values().next().unwrap();
        assert!(!static_card.replacement.contains("customDynamicConfig"));
        assert!(!static_only.sheets.custom.contains("-dyn-"));
        assert!(!static_only.dynamic_props.contains_key("size"));

        let dynamic = analyze(
            &[(
                "a.tsx",
                "export const Card = ds.props({ size: { property: 'flexBasis' } }).asElement('div');\nexport const App = ({ value }) => <Card size={value} />;\n",
            )],
            &test_inputs(),
        );
        let dynamic_card = dynamic.components.values().next().unwrap();
        assert!(dynamic_card.replacement.contains("customDynamicConfig"));
        // The runtime derives the slot's names from the scope.
        assert!(dynamic_card.replacement.contains(r#""scope":["animus","Card_"#), "{}", dynamic_card.replacement);
        assert!(!dynamic_card.replacement.contains("animus-dyn-"));
        assert!(dynamic.sheets.custom.contains("@layer anm-custom"));
        assert!(!dynamic.dynamic_props.contains_key("size"));
    }

    #[test]
    fn known_values_through_isolatable_callbacks_extract_beside_their_runtime_path() {
        let source = r#"import { createTransform as ct } from '@animus-ui/system';
const double = (v: number) => v * 2;
function half(v) { return `${v / 2}px`; }
const named = ct('triple', (v) => `${v * 3}px`);
const factor = 4;
const closed = (v) => `${v * factor}px`;
export const Box = ds
  .props({
    inl: { property: 'minWidth', transform: (v) => v * 2 },
    loc: { property: 'minHeight', transform: double },
    fn: { property: 'maxWidth', transform: half },
    ct: { property: 'marginLeft', transform: named },
    shut: { property: 'marginTop', transform: closed },
  })
  .asElement('div');
export const App = ({ n }) => (
  <Box inl={10} loc={10} fn={10} ct={10} shut={10} {...n} />
);
"#;
        let out = analyze(&[("a.tsx", source)], &test_inputs());
        let custom = &out.sheets.custom;
        for declaration in [
            "min-width: 20;",
            "min-height: 20;",
            "max-width: 5px;",
            "margin-left: 30px;",
        ] {
            assert!(custom.contains(declaration), "{declaration} missing:\n{custom}");
        }
        // The closure cannot be isolated: its value stays on the runtime path.
        assert!(!custom.contains("margin-top: 10"), "{custom}");
        assert!(!custom.contains("margin-top: 40px"), "{custom}");

        let payload = &out.replacement_configs["a.tsx::Box"];
        let classes = payload.custom_prop_class_map.as_ref().unwrap();
        for prop in ["inl", "loc", "fn", "ct"] {
            assert!(classes[prop].contains_key("10"), "{prop}: {classes:?}");
        }
        assert!(classes["shut"].is_empty(), "{classes:?}");
        // Every callback keeps its delivery for values the build cannot know.
        let dynamic = payload.custom_dynamic_config.as_ref().unwrap();
        for prop in ["inl", "loc", "fn", "ct", "shut"] {
            assert!(dynamic[prop].value().unwrap().transform_fn_source.is_some(), "{prop}");
        }
        assert_eq!(
            out.diagnostics.iter().filter(|d| d.component == "Box").count(),
            0,
            "{:?}",
            out.diagnostics
        );
    }

    fn custom_classes<'a>(out: &'a CssOutput, id: &str, prop: &str) -> &'a HashMap<String, String> {
        &out.replacement_configs[id].custom_prop_class_map.as_ref().unwrap()[prop]
    }

    #[test]
    fn runtime_scale_values_reach_assets_through_a_root_variable() {
        let source = r#"export const Box = ds
  .props({ texture: { property: 'backgroundImage', scale: 'images' } })
  .system({ space: true })
  .asElement('div');
export const App = ({ n }) => <Box bgImage={n} texture={n} />;
"#;
        let mut inputs = CssInputs::from_json(
            None,
            None,
            None,
            Some(r#"{"bgImage": {"property": "backgroundImage", "scale": "images"}}"#),
            Some(r#"{"space": ["bgImage"]}"#),
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            false,
        )
        .unwrap();
        let rock = r#"url("animus-asset:@acme/media/rock.jpg")"#;
        inputs.theme.insert("images.rock".into(), rock.into());
        inputs.theme.insert("images.none".into(), "none".into());
        let out = analyze(&[("a.tsx", source)], &inputs);

        let reference = format!("var(--animus-asset-{})", crate::css::content_hash(rock));
        let system = out.dynamic_props["bgImage"].value().unwrap();
        assert_eq!(system.scale_values["rock"], serde_json::Value::String(reference.clone()));
        assert_eq!(system.scale_values["none"], "none");
        let payload = &out.replacement_configs["a.tsx::Box"];
        let custom = payload.custom_dynamic_config.as_ref().unwrap()["texture"].value().unwrap();
        assert_eq!(custom.scale_values["rock"], serde_json::Value::String(reference));
        assert!(
            out.sheets.global.contains(&format!("--animus-asset-{}: {rock};", crate::css::content_hash(rock))),
            "{}",
            out.sheets.global
        );
        let manifest = serde_json::to_string(&out.dynamic_props).unwrap();
        assert!(!manifest.contains("animus-asset:"), "{manifest}");
        assert!(!out.components["a.tsx::Box"].replacement.contains("animus-asset:"));
    }

    /// Two keys of one block on one CSS property at one condition warn when
    /// one has no effect or a longhand is written before its shorthand,
    /// naming the one that takes effect; a shorthand followed by its
    /// longhand is the override idiom and stays quiet. The cascade rule is
    /// unchanged.
    #[test]
    fn two_keys_on_one_property_warn_naming_the_one_that_takes_effect() {
        let mut inputs = CssInputs::from_json(
            None,
            None,
            None,
            Some(r#"{"p": {"property": "padding"}, "padding": {"property": "padding"}, "m": {"property": "margin"}}"#),
            Some(r#"{"probe": ["p", "padding", "m"]}"#),
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            false,
        )
        .unwrap();
        inputs.theme.insert("breakpoints.sm".into(), "480".into());
        let source = "export const Box = ds.styles({ padding: '1px', p: '2px', '&:hover': { marginTop: '3px', m: '4px' } }).asElement('div');\n\
             export const Quiet = ds.styles({ p: { sm: '8px' }, padding: '1px', margin: '1px', marginTop: '2px', '&:focus': { paddingTop: '2px' } }).asElement('span');\n\
             export const App = () => <><Box /><Quiet /></>;\n";
        let out = analyze(&[("a.tsx", source)], &inputs);
        let warnings: Vec<(&str, &str)> = out
            .diagnostics
            .iter()
            .filter(|d| d.code.as_deref() == Some(crate::theme::KEYS_SHARE_PROPERTY))
            .map(|d| (d.component.as_str(), d.message.as_str()))
            .collect();
        assert_eq!(
            warnings,
            [
                (
                    "Box",
                    "style keys 'padding' and 'p' both set padding, so 'padding' has no effect: 'p', the later \
                     key, takes effect — remove one"
                ),
                (
                    "Box",
                    "style key 'marginTop' comes before 'm', which also sets margin-top: in plain CSS 'm' would \
                     reset it, but a longhand applies after its shorthand, so 'marginTop' takes effect"
                ),
            ]
        );
        // The rule itself stands: the alias written later, and the longhand.
        let base = out.sheets.base.split_whitespace().collect::<Vec<_>>().join(" ");
        assert!(base.contains("padding: 1px; padding: 2px;"), "{base}");
        assert!(base.contains("margin: 4px; margin-top: 3px;"), "{base}");
    }

    #[test]
    fn no_runtime_asset_leaves_the_global_sheet_alone() {
        let source = "export const Box = ds.system({ space: true }).asElement('div');\nexport const App = ({ n }) => <Box p={n} />;\n";
        let out = analyze(&[("a.tsx", source)], &test_inputs());
        // Only the slot variables' registrations lead it; no asset rule follows.
        assert!(out.sheets.global.lines().all(|line| line.starts_with("@property --animus-p_")), "{}", out.sheets.global);
    }

    #[test]
    fn only_literal_css_wide_keywords_produce_keyword_css() {
        let source = "export const Box = ds.system({ space: true }).asElement('div');\n\
                      export const App = ({ n }) => <><Box p={n} /><Box p=\"inherit\" /></>;\n";
        let out = analyze(&[("a.tsx", source)], &test_inputs());
        let p = &out.system_prop_map["p"];
        assert_eq!(p.keys().collect::<Vec<_>>(), ["inherit"], "{p:?}");
        assert!(out.sheets.system.contains("padding: inherit;"), "{}", out.sheets.system);
        for keyword in ["initial", "unset", "revert;", "revert-layer"] {
            assert!(!out.sheets.system.contains(&format!("padding: {keyword}")), "{}", out.sheets.system);
        }
        assert!(out.dynamic_props.contains_key("p"));
    }

    #[test]
    fn an_explicit_undefined_jsx_prop_is_an_omitted_prop() {
        let source = "const Box = ds.styles({ display: 'block' })\n\
                      .variant({ prop: 'size', defaultVariant: 'md', variants: { sm: { gap: '1px' }, md: { gap: '2px' }, lg: { gap: '3px' } } })\n\
                      .system({ space: true }).asElement('div');\n\
                      export const App = () => <><Box size={undefined} /><Box p={{ _: 8, sm: undefined, md: null }} /></>;\n";
        let out = analyze(&[("a.tsx", source)], &test_inputs());
        // As when `size` is omitted, only the default option is used.
        assert!(!out.sheets.variants.contains("--size-sm") && !out.sheets.variants.contains("--size-lg"), "{}", out.sheets.variants);
        assert!(out.sheets.variants.contains("--size-default"), "{}", out.sheets.variants);
        // The nullish breakpoints are absent, so the value takes the class
        // `{ _: 8 }` takes.
        assert_eq!(out.system_prop_map["p"].keys().collect::<Vec<_>>(), ["_:8"]);
    }

    #[test]
    fn slots_follow_the_usage_a_complete_analysis_proves_across_modules() {
        let kit = "export const Box = ds.system({ space: true }).asElement('div');\n";
        let slots = |app: &str, inputs: &CssInputs| {
            let out = analyze(&[("kit.tsx", kit), ("app.tsx", app)], inputs);
            out.dynamic_props.keys().cloned().collect::<Vec<_>>()
        };
        let cases: [(&str, &[&str]); 29] = [
            ("export const App = () => <Box p={8} />;\n", &[]),
            ("export const App = ({ n }) => <Box p={n} />;\n", &["p"]),
            // A spread, an escape or a component chosen at runtime leaves a
            // use unproven, and an unanalysed receiver may clone props in.
            ("export const App = (rest) => <Box {...rest} />;\n", &["p"]),
            ("export const list = [Box];\nexport const App = () => <Box p={8} />;\n", &["p"]),
            ("export const App = ({ As }) => <As><Box p={8} /></As>;\n", &["p"]),
            ("import { Slot } from 'ui-lib';\nexport const App = () => <Slot><Box p={8} /></Slot>;\n", &["p"]),
            // An analysed ordinary component and React's pass-through
            // components leave every use proven.
            ("function Card({ children }) { return <div>{children}</div>; }\nexport const App = () => <Card><Box p={8} /></Card>;\n", &[]),
            ("import { StrictMode } from 'react';\nexport const App = () => <StrictMode><Box p={8} /></StrictMode>;\n", &[]),
            // React's names count only through an import from React.
            ("import { StrictMode } from 'ui-lib';\nexport const App = () => <StrictMode><Box p={8} /></StrictMode>;\n", &["p"]),
            // Code outside the analysis that receives an element can clone
            // props into it: an element in such a call's arguments, or a
            // parameter an ordinary component passes to one.
            ("import { enhance } from 'ui-lib';\nexport const App = () => <div>{enhance(<Box p={8} />)}</div>;\n", &["p"]),
            ("import { useRender } from '@base-ui/react';\nexport const App = ({ props }) => useRender({ render: <Box p={8} />, props });\n", &["p"]),
            ("import { useRender } from '@base-ui/react';\nfunction Button({ render, ...props }) { return useRender({ render, props }); }\nexport const App = () => <Button render={<Box p={8} />} />;\n", &["p"]),
            // So does a module value built from such code, an element or a
            // parameter several `const`s away, and a `new` expression.
            ("import * as lib from 'ui-lib';\nconst enhance = lib.enhance;\nexport const App = () => <div>{enhance(<Box p={8} />)}</div>;\n", &["p"]),
            ("import { enhance as e } from 'ui-lib';\nconst enhance = e;\nexport const App = () => <div>{enhance(<Box p={8} />)}</div>;\n", &["p"]),
            ("import { create } from 'ui-lib';\nconst enhance = create();\nexport const App = () => <div>{enhance(<Box p={8} />)}</div>;\n", &["p"]),
            ("import { useRender } from '@base-ui/react';\nexport const App = ({ props }) => { const el = <Box p={8} />; const opts = { render: el, props }; return useRender(opts); };\n", &["p"]),
            ("import { useRender } from '@base-ui/react';\nfunction Button(props) { const r = props.render; const opts = { render: r }; return useRender(opts); }\nexport const App = () => <Button render={<Box p={8} />} />;\n", &["p"]),
            ("import { Widget } from 'ui-lib';\nexport const App = () => { new Widget(<Box p={8} />); return null; };\n", &["p"]),
            // A render function the call receives can return the element, and
            // a value built through a function reads what that function reads.
            ("import { enhance } from 'ui-lib';\nconst renderIcon = () => <Box p={8} />;\nexport const App = () => <div>{enhance(renderIcon)}</div>;\n", &["p"]),
            ("import { useRender } from '@base-ui/react';\nexport const App = ({ props }) => { const render = () => <Box p={8} />; return useRender({ render, props }); };\n", &["p"]),
            ("import { enhance } from 'ui-lib';\nfunction renderIcon() { return <Box p={8} />; }\nexport const App = () => <div>{enhance(renderIcon)}</div>;\n", &["p"]),
            ("import * as lib from 'ui-lib';\nfunction getEnhance() { return lib.enhance; }\nconst enhance = getEnhance();\nexport const App = () => <div>{enhance(<Box p={8} />)}</div>;\n", &["p"]),
            ("import { enhance } from 'ui-lib';\nconst icons = { a: <Box p={8} /> };\nconst { a } = icons;\nexport const App = () => <div>{enhance(a)}</div>;\n", &["p"]),
            // A pattern's defaults, and a parameter a function captures.
            ("import { enhance } from 'ui-lib';\nconst { a = <Box p={8} /> } = {};\nexport const App = () => <div>{enhance(a)}</div>;\n", &["p"]),
            ("import { enhance } from 'ui-lib';\nconst [a = <Box p={8} />] = [];\nexport const App = () => <div>{enhance(a)}</div>;\n", &["p"]),
            ("import * as lib from 'ui-lib';\nconst { enhance = lib.enhance } = {};\nexport const App = () => <div>{enhance(<Box p={8} />)}</div>;\n", &["p"]),
            ("import { enhance } from 'ui-lib';\nfunction Button(props) { const getRender = () => props.render; return enhance(getRender()); }\nexport const App = () => <Button render={<Box p={8} />} />;\n", &["p"]),
            // React's own calls and calls on the module's values stay proven.
            ("import { useMemo } from 'react';\nexport const App = () => useMemo(() => <Box p={8} />, []);\n", &[]),
            ("const items = [1, 2];\nexport const App = () => <>{items.map((i) => <Box key={i} p={8} />)}</>;\n", &[]),
        ];
        for (app, want) in cases {
            let app = format!("import {{ Box }} from './kit';\n{app}");
            assert_eq!(slots(&app, &test_inputs()), want, "{app}");
        }
        // An element another module's `const` or default export holds.
        for (els, import) in [
            ("import { Box } from './kit';\nexport const icon = <Box p={8} />;\n", "import { icon } from './els';"),
            ("import { Box } from './kit';\nexport default <Box p={8} />;\n", "import icon from './els';"),
            ("import { Box } from './kit';\nexport default function () { return <Box p={8} />; }\n", "import icon from './els';"),
        ] {
            let app = format!("{import}\nimport {{ enhance }} from 'ui-lib';\nexport const App = () => <div>{{enhance(icon)}}</div>;\n");
            let out = analyze(&[("kit.tsx", kit), ("els.tsx", els), ("app.tsx", &app)], &test_inputs());
            assert_eq!(out.dynamic_props.keys().collect::<Vec<_>>(), ["p"], "{els}");
        }
        let mut dev = test_inputs();
        dev.dev_mode = true;
        assert_eq!(slots("import { Box } from './kit';\nexport const App = () => <Box p={8} />;\n", &dev), ["p"]);
    }

    /// A private wrapper's spread carries only its renders, and an
    /// `.asComponent()` target's spread only what the component's own uses
    /// forward, every prop but its variants, states and system props: both
    /// leave the component they render proven. A use the analysis cannot
    /// read, of the wrapper or of the component, keeps its slots, and so
    /// does the class string the runtime builds for the target itself.
    #[test]
    fn forwarding_spreads_carry_only_the_uses_that_reach_them() {
        let kit = "export const Box = ds.system({ space: true }).asElement('div');\n";
        let wrapper = "const W = (props) => <Box as=\"span\" {...props} />;\n";
        let target = "function El(props) { return <Box as=\"span\" {...props} />; }\n\
                      const Media = Box.extend().styles({ display: 'flex' }).asComponent(El);\n";
        let cases: [(String, &[&str]); 7] = [
            (format!("{wrapper}export const App = () => <W p={{8}} />;\n"), &[]),
            (format!("{wrapper}export const App = (rest) => <W {{...rest}} />;\n"), &["p"]),
            (format!("{target}export const App = () => <Media p={{8}} />;\n"), &[]),
            (format!("{target}export const App = (rest) => <Media {{...rest}} />;\n"), &["p"]),
            (format!("{target}export const list = [Media];\n"), &["p"]),
            (format!("{target}export const App = ({{ n }}) => <><Media /><El p={{n}} /></>;\n"), &["p"]),
            (format!("{target}export const App = () => <Media />;\nexport const made = make(El);\n"), &["p"]),
        ];
        for (app, want) in cases {
            let app = format!("import {{ Box }} from './kit';\n{app}");
            let out = analyze(&[("kit.tsx", kit), ("app.tsx", &app)], &test_inputs());
            assert_eq!(out.dynamic_props.keys().collect::<Vec<_>>(), want, "{app}");
        }
        let class_prop = CssInputs::from_json(
            None,
            None,
            None,
            Some(r#"{"className": {"property": "--observed"}}"#),
            Some(r#"{"special": ["className"]}"#),
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            false,
        )
        .unwrap();
        let kit = "export const Special = ds.system({ special: true }).asElement('div');\n\
                   export const Base = ds.styles({ display: 'block' }).asElement('div');\n";
        for render in ["<Outer />", "<Outer className=\"red\" />"] {
            let app = format!(
                "import {{ Base, Special }} from './kit';\n\
                 function El(props) {{ return <Special as=\"span\" {{...props}} />; }}\n\
                 const Outer = Base.extend().asComponent(El);\nexport const App = () => {render};\n"
            );
            let out = analyze(&[("kit.tsx", kit), ("app.tsx", &app)], &class_prop);
            assert_eq!(out.dynamic_props.keys().collect::<Vec<_>>(), ["className"], "{render}");
            assert!(!out.system_prop_map.contains_key("className"), "{render}: {:?}", out.system_prop_map);
        }
    }

    /// Contract: a variant an `.asComponent()` terminal forwards reaches the
    /// target where no use writes it, as its default, so a component the
    /// target renders by spread keeps the slot that value fills. One the
    /// terminal does not forward is the runtime's and reaches nothing.
    #[test]
    fn forwarded_defaults_reach_what_the_target_renders() {
        let kit = "export const Box = ds.system({ space: true }).asElement('div');\n\
                   export const Base = ds.styles({ display: 'block' })\n\
                   .variant({ prop: 'p', defaultVariant: 'sm', variants: { sm: { display: 'flex' }, lg: { display: 'grid' } } })\n\
                   .asElement('div');\n";
        let cases: [(&str, &[&str]); 3] = [("", &[]), (", { forward: ['p'] }", &["p"]), (", { forward: true }", &["p"])];
        for (forward, want) in cases {
            let app = format!(
                "import {{ Box, Base }} from './kit';\n\
                 function El(props) {{ return <Box as=\"span\" {{...props}} />; }}\n\
                 const Outer = Base.extend().asComponent(El{forward});\nexport const App = () => <Outer />;\n"
            );
            let out = analyze(&[("kit.tsx", kit), ("app.tsx", &app)], &test_inputs());
            assert_eq!(out.dynamic_props.keys().collect::<Vec<_>>(), want, "{forward}");
        }
    }

    /// An identity-uncertain tag blocks only what it can reach. A tag that
    /// can only receive our elements (an import from an unanalysed package,
    /// a member of one, or an ordinary component that passes its children
    /// to one) opens just the components whose elements it receives; a tag
    /// that may be one of our components (a parameter, a relative import
    /// extraction cannot read), or a `createElement` receiver, whose children
    /// are not followed as delivered, still blocks every component.
    #[test]
    fn uncertain_tags_block_only_what_they_can_reach() {
        let kit = "export const Box = ds.system({ space: true }).asElement('div');\n";
        let slots = |app: &str| {
            let app = format!("import {{ Box }} from './kit';\n{app}");
            let out = analyze(&[("kit.tsx", kit), ("app.tsx", &app)], &test_inputs());
            out.dynamic_props.keys().cloned().collect::<Vec<_>>()
        };
        let cases: [(&str, &[&str]); 7] = [
            ("import { Slot } from 'ui-lib';\nexport const App = () => <><Slot><div /></Slot><Box p={8} /></>;\n", &[]),
            ("import * as Dialog from 'ui-lib/dialog';\nexport const App = () => <><Dialog.Root><div /></Dialog.Root><Box p={8} /></>;\n", &[]),
            ("import { Slot } from 'ui-lib';\nfunction Card({ children }) { return <Slot>{children}</Slot>; }\nexport const App = () => <><Card><div /></Card><Box p={8} /></>;\n", &[]),
            ("import { Slot } from 'ui-lib';\nexport const App = () => <><Slot><Box p={8} /></Slot><Box p={8} /></>;\n", &["p"]),
            ("export const App = ({ As }) => <><As /><Box p={8} /></>;\n", &["p"]),
            ("import { Mystery } from './external';\nexport const App = () => <><Mystery /><Box p={8} /></>;\n", &["p"]),
            ("import { createElement } from 'react';\nimport { Slot } from 'ui-lib';\nexport const App = () => <><Slot><div /></Slot>{createElement(Slot, null, <Box p={8} />)}</>;\n", &["p"]),
        ];
        for (app, want) in cases {
            assert_eq!(slots(app), want, "{app}");
        }
    }

    /// A private spread wrapper held by a member of an object literal
    /// (`const Code = { Header }`) renders through `<Code.Header>` in any
    /// module, so those renders stand in for its renders. Any other route
    /// to it (the object or the member as a value, a copy of the object, a
    /// write to it, or the wrapper anywhere else), and a member tag whose
    /// first name a parameter or local binds, keeps its target's slots.
    #[test]
    fn object_held_wrappers_render_through_member_tags() {
        let kit = "export const Box = ds.system({ space: true }).asElement('div');\n";
        let family = "import { Box } from './kit';\n\
                      function Header(props) { return <Box as=\"span\" {...props} />; }\n\
                      export const Code = { Header };\n";
        let cases: [(&str, &str, &[&str]); 13] = [
            ("", "import { Code } from './fam';\nexport const App = () => <Code.Header p={8} />;\n", &[]),
            // A parameter or local of the object's name is another value.
            ("", "import { Code } from './fam';\nexport const App = ({ Code }) => <Code.Header p={8} />;\n", &["p"]),
            ("", "import { Code } from './fam';\nexport const App = () => { const Code = getCode(); return <Code.Header p={8} />; };\n", &["p"]),
            ("", "import * as ui from './fam';\nexport const App = () => <ui.Code.Header p={8} />;\n", &[]),
            ("", "import { Code } from './fam';\nexport const App = (rest) => <Code.Header {...rest} />;\n", &["p"]),
            ("", "import { Code } from './fam';\nexport const App = ({ n }) => <Code.Header p={n} />;\n", &["p"]),
            ("", "import { Code } from './fam';\nexport const all = Object.values(Code);\n", &["p"]),
            ("", "import { Code } from './fam';\nexport const H = Code.Header;\n", &["p"]),
            ("", "import { Code } from './fam';\nexport const More = { ...Code };\n", &["p"]),
            ("Code.Header = () => null;\n", "import { Code } from './fam';\nexport const App = () => <Code.Header p={8} />;\n", &["p"]),
            ("register(Code);\n", "import { Code } from './fam';\nexport const App = () => <Code.Header p={8} />;\n", &["p"]),
            ("export const list = [Header];\n", "import { Code } from './fam';\nexport const App = () => <Code.Header p={8} />;\n", &["p"]),
            ("export const Other = { Header };\n", "import { Code, Other } from './fam';\nexport const App = ({ n }) => <><Code.Header p={8} /><Other.Header p={n} /></>;\n", &["p"]),
        ];
        for (more, app, want) in cases {
            let family = format!("{family}{more}");
            let out = analyze(&[("kit.tsx", kit), ("fam.tsx", family.as_str()), ("app.tsx", app)], &test_inputs());
            assert_eq!(out.dynamic_props.keys().collect::<Vec<_>>(), want, "{more}{app}");
        }
    }

    /// A direct `createElement` call on an extracted component records the
    /// literal system props JSX records for the same element, so they take
    /// static classes, through parentheses and type-only wrappers and past an
    /// absent breakpoint; props it spreads are the element's spread.
    #[test]
    fn create_element_records_literal_system_props_as_jsx_does() {
        let kit = "export const Box = ds.system({ space: true }).asElement('div');\n";
        let analyzed = |app: &str| {
            let app = format!("import {{ Box }} from './kit';\nimport {{ createElement }} from 'react';\n{app}");
            analyze(&[("kit.tsx", kit), ("app.tsx", &app)], &test_inputs())
        };
        let keys = |out: &CssOutput| out.system_prop_map.get("p").map(|map| map.keys().cloned().collect::<Vec<_>>());
        let unread = |out: &CssOutput| {
            out.diagnostics.iter().filter(|d| d.code.as_deref() == Some(UNREAD_CREATE_ELEMENT_PROPS)).count()
        };
        for (call, jsx) in [
            ("createElement(Box, { p: 8 })", "<Box p={8} />"),
            ("createElement(Box, { p: { _: 8, sm: 16 } })", "<Box p={{ _: 8, sm: 16 }} />"),
            ("React.createElement(Box, { p: 8, id: 'a' })", "<Box p={8} id=\"a\" />"),
            ("createElement(Box, { p: { _: 8, md: undefined, sm: 16 } })", "<Box p={{ _: 8, md: undefined, sm: 16 }} />"),
            ("createElement(Box, ({ p: 8 }))", "<Box p={8} />"),
            ("createElement(Box, ({ p: 8 } as const))", "<Box p={8} />"),
            ("createElement(Box, ({ p: 8 } satisfies Record<string, number>))", "<Box p={8} />"),
        ] {
            let by_call = analyzed(&format!("export const App = () => {call};\n"));
            let by_jsx = analyzed(&format!("export const App = () => {jsx};\n"));
            assert_eq!(keys(&by_call), keys(&by_jsx), "{call}");
            assert!(keys(&by_call).is_some(), "{call}");
            assert_eq!(unread(&by_call), 0, "{call}");
        }
        // Props it spreads are the element's spread, as in JSX: no warning
        // of its own.
        for (call, jsx) in [
            ("createElement(Box, props)", "<Box {...props} />"),
            ("createElement(Box, { ...props, p: 8 })", "<Box {...props} p={8} />"),
        ] {
            let by_call = analyzed(&format!("export const App = (props) => {call};\n"));
            let by_jsx = analyzed(&format!("export const App = (props) => {jsx};\n"));
            assert_eq!(keys(&by_call), keys(&by_jsx), "{call}");
            assert_eq!(unread(&by_call), 0, "{call}");
        }
        let shadowed = analyzed("export const App = ({ Box, props }) => createElement(Box, props);\n");
        assert_eq!(unread(&shadowed), 0);
    }

    /// A spread whose every branch is an object literal of literal entries,
    /// or nothing (`{...(c ? { p: 8 } : {})}`), writes those entries on the
    /// branches that hold them: they take static classes, and the prop keeps
    /// its default where a branch leaves it out. Any other spread writes
    /// anything.
    #[test]
    fn listed_spreads_write_the_entries_their_branches_hold() {
        let kit = "export const Box = ds.system({ space: true }).asElement('div');\n";
        let cases: [(&str, &[&str]); 6] = [
            ("<Box {...(c ? { p: 8 } : {})} />", &[]),
            ("<Box {...(c && { p: 8 })} />", &[]),
            ("<Box {...(c ? { p: 8 } : null)} />", &[]),
            ("<Box {...(c ? { p: n } : {})} />", &["p"]),
            ("<Box {...(c ? o : {})} />", &["p"]),
            ("<Box {...(c || 'abc')} />", &["p"]),
        ];
        for (render, want) in cases {
            let app = format!("import {{ Box }} from './kit';\nexport const App = ({{ c, n, o }}) => {render};\n");
            let out = analyze(&[("kit.tsx", kit), ("app.tsx", &app)], &test_inputs());
            assert_eq!(out.dynamic_props.keys().collect::<Vec<_>>(), want, "{render}");
        }
        for (render, sizes) in [
            ("<R {...(c ? { size: 'lg' } : {})} />", vec!["md", "lg"]),
            ("<R size=\"sm\" {...(c ? { size: 'lg' } : {})} />", vec!["sm", "lg"]),
            ("<R {...(c ? o : {})} />", vec!["sm", "md", "lg"]),
        ] {
            let app = format!("import {{ R }} from './r';\nexport const App = ({{ c, o }}) => {render};\n");
            assert_eq!(kept_options(&[("r.tsx", RECIPE), ("app.tsx", app.as_str())]).0, sizes, "{render}");
        }
    }

    /// A member tag that names an ordinary function component a stable
    /// object holds (`<Dialog.Root>` for `const Dialog = { Root }`) is that
    /// component: it leaves usage proven, and its children stay in place
    /// unless it passes them to code outside the analysis, children a local
    /// takes by assignment included. A member the object may no longer hold
    /// (in any module), one built by a call, or a parameter that shares the
    /// object's name still blocks.
    #[test]
    fn ordinary_family_members_leave_usage_proven() {
        let kit = "export const Box = ds.system({ space: true }).asElement('div');\n";
        let family = "import { Slot } from 'ui-lib';\n\
                      function Root({ children }) { return <section>{children}</section>; }\n\
                      function Pass({ children }) { return <Slot>{children}</Slot>; }\n\
                      function Held({ children }) { let held; held = children; return <Slot>{held}</Slot>; }\n\
                      export const Dialog = { Root, Pass, Held, Made: memo(Root) };\n";
        let cases: [(&str, &str, &[&str]); 8] = [
            ("", "() => <><Dialog.Root /><Box p={8} /></>", &[]),
            ("", "() => <Dialog.Root><Box p={8} /></Dialog.Root>", &[]),
            ("", "() => <><Dialog.Pass><div /></Dialog.Pass><Box p={8} /></>", &[]),
            ("", "() => <><Dialog.Pass><Box p={8} /></Dialog.Pass><Box p={8} /></>", &["p"]),
            // Children a local takes by assignment may still be passed on.
            ("", "() => <><Dialog.Held><Box p={8} /></Dialog.Held><Box p={8} /></>", &["p"]),
            ("", "() => <><Dialog.Made /><Box p={8} /></>", &["p"]),
            ("", "({ Dialog }) => <><Dialog.Root /><Box p={8} /></>", &["p"]),
            ("Dialog.Root = maybe;\n", "() => <><Dialog.Root /><Box p={8} /></>", &["p"]),
        ];
        for (more, app, want) in cases {
            let family = format!("{family}{more}");
            let app = format!("import {{ Box }} from './kit';\nimport {{ Dialog }} from './fam';\nexport const App = {app};\n");
            let out = analyze(&[("kit.tsx", kit), ("fam.tsx", family.as_str()), ("app.tsx", app.as_str())], &test_inputs());
            assert_eq!(out.dynamic_props.keys().collect::<Vec<_>>(), want, "{more}{app}");
        }
        // A module with no import still records what may change its object.
        let plain = "function Root({ children }) { return <section>{children}</section>; }\nexport const Dialog = { Root };\n";
        for more in ["consume(Dialog);\n", "delete Dialog.Root;\nrestore(Dialog);\n"] {
            let family = format!("{plain}{more}");
            let app = "import { Box } from './kit';\nimport { Dialog } from './fam';\n\
                       export const App = () => <Dialog.Root><Box p={8} /></Dialog.Root>;\n";
            let out = analyze(&[("kit.tsx", kit), ("fam.tsx", family.as_str()), ("app.tsx", app)], &test_inputs());
            assert_eq!(out.dynamic_props.keys().collect::<Vec<_>>(), ["p"], "{more}");
        }
    }

    /// A tag whose first name a parameter or local binds is not the module's
    /// binding of that name: `({ Fam }) => <Fam.Root p={n} />` may render
    /// any component, so its runtime value keeps every component's slot,
    /// where the imported `Fam.Root` would carry it to a component that
    /// takes no `p`.
    #[test]
    fn tags_resolve_through_their_root_binding() {
        let kit = "export const Plain = ds.styles({ display: 'flex' }).asElement('div');\n\
                   export const Other = ds.system({ space: true }).asElement('div');\n\
                   export const Fam = compose({ Root: Plain }, { name: 'Fam' });\n";
        let cases: [(&str, &[&str]); 5] = [
            ("({ Fam, n }) => <Fam.Root p={n} />", &["p"]),
            ("({ n }) => { const Fam = pick(); return <Fam.Root p={n} />; }", &["p"]),
            ("({ Plain, n }) => <Plain p={n} />", &["p"]),
            ("({ Fam, n }) => createElement(Fam.Root, { p: n })", &["p"]),
            ("({ n }) => <Fam.Root p={n} />", &[]),
        ];
        for (app, want) in cases {
            let app = format!(
                "import {{ Fam, Plain, Other }} from './kit';\nimport {{ createElement }} from 'react';\n\
                 export const App = {app};\nexport const B = () => <Other p={{8}} />;\n"
            );
            let out = analyze(&[("kit.tsx", kit), ("app.tsx", app.as_str())], &test_inputs());
            assert_eq!(out.dynamic_props.keys().collect::<Vec<_>>(), want, "{app}");
        }
    }

    /// A member tag that names a component of a package extraction does not
    /// analyse, held by a stable object (`Trigger: ArkMenu.Trigger`), can
    /// only receive our elements: it leaves usage proven, and the elements
    /// it receives open as a package receiver's do. A member the object may
    /// no longer hold, one from an analysed module, or a parameter sharing
    /// the object's name still blocks.
    #[test]
    fn package_family_members_leave_usage_proven() {
        let kit = "export const Box = ds.system({ space: true }).asElement('div');\n";
        let local = "export function Trigger({ children }) { return <button>{children}</button>; }\n";
        let family = "import { Menu as ArkMenu, Slot } from 'ui-lib';\nimport * as Local from './local';\n\
                      export const Menu = { Trigger: ArkMenu.Trigger, Item: Slot, Own: Local.Trigger };\n";
        let cases: [(&str, &str, &[&str]); 6] = [
            ("", "() => <><Menu.Trigger><div /></Menu.Trigger><Box p={8} /></>", &[]),
            ("", "() => <><Menu.Item><div /></Menu.Item><Box p={8} /></>", &[]),
            ("", "() => <><Menu.Trigger><Box p={8} /></Menu.Trigger><Box p={8} /></>", &["p"]),
            ("", "() => <><Menu.Own><div /></Menu.Own><Box p={8} /></>", &["p"]),
            ("", "({ Menu }) => <><Menu.Trigger><div /></Menu.Trigger><Box p={8} /></>", &["p"]),
            ("Menu.Trigger = maybe;\n", "() => <><Menu.Trigger><div /></Menu.Trigger><Box p={8} /></>", &["p"]),
        ];
        for (more, app, want) in cases {
            let family = format!("{family}{more}");
            let app = format!("import {{ Box }} from './kit';\nimport {{ Menu }} from './fam';\nexport const App = {app};\n");
            let out = analyze(
                &[("kit.tsx", kit), ("local.tsx", local), ("fam.tsx", family.as_str()), ("app.tsx", app.as_str())],
                &test_inputs(),
            );
            assert_eq!(out.dynamic_props.keys().collect::<Vec<_>>(), want, "{more}{app}");
        }
    }

    /// The `Provider` of a context React's `createContext` builds as a
    /// module-scope `const` renders its children in place: it leaves usage
    /// proven, in its module or through an import. A context built another
    /// way, one something may change, one a parameter shadows, or its
    /// `Consumer` still blocks.
    #[test]
    fn context_providers_leave_usage_proven() {
        let kit = "export const Box = ds.system({ space: true }).asElement('div');\n";
        let contexts = "import { createContext } from 'react';\nexport const Shared = createContext(null);\n";
        let cases: [(&str, &str, &[&str]); 7] = [
            ("import { createContext } from 'react';\nconst Theme = createContext<number>(0);",
             "() => <><Theme.Provider value={1}><div /></Theme.Provider><Box p={8} /></>", &[]),
            ("import * as React from 'react';\nconst Theme = React.createContext(0);",
             "() => <Theme.Provider value={1}><Box p={8} /></Theme.Provider>", &[]),
            ("import { Shared } from './contexts';",
             "() => <><Shared.Provider value={1}><div /></Shared.Provider><Box p={8} /></>", &[]),
            ("const createContext = (v) => ({ Provider: pick(v) });\nconst Theme = createContext(0);",
             "() => <><Theme.Provider value={1} /><Box p={8} /></>", &["p"]),
            ("import { createContext } from 'react';\nlet Theme = createContext(0);",
             "() => <><Theme.Provider value={1} /><Box p={8} /></>", &["p"]),
            ("import { Shared } from './contexts';",
             "({ Shared }) => <><Shared.Provider value={1} /><Box p={8} /></>", &["p"]),
            ("import { Shared } from './contexts';",
             "() => <><Shared.Consumer>{() => null}</Shared.Consumer><Box p={8} /></>", &["p"]),
        ];
        for (setup, app, want) in cases {
            let app = format!("import {{ Box }} from './kit';\n{setup}\nexport const App = {app};\n");
            let out = analyze(&[("kit.tsx", kit), ("contexts.tsx", contexts), ("app.tsx", app.as_str())], &test_inputs());
            assert_eq!(out.dynamic_props.keys().collect::<Vec<_>>(), want, "{app}");
        }
        // Only an import binds React: a local or an unbound `React` is not it.
        let fake = "const React = { createContext: (v) => ({ Provider: pick(v) }) };\n";
        for made in [
            format!("{fake}export const Made = React.createContext(0);\n"),
            format!("import {{ x }} from 'somewhere';\n{fake}export const Made = React.createContext(0);\n"),
            "export const Made = React.createContext(0);\n".to_string(),
            "import React from 'react';\nReact.createContext = pick;\nexport const Made = React.createContext(0);\n".to_string(),
        ] {
            let app = "import { Box } from './kit';\nimport { Made } from './made';\n\
                       export const App = () => <><Made.Provider value={1}><div /></Made.Provider><Box p={8} /></>;\n";
            let out = analyze(&[("kit.tsx", kit), ("made.tsx", made.as_str()), ("app.tsx", app)], &test_inputs());
            assert_eq!(out.dynamic_props.keys().collect::<Vec<_>>(), ["p"], "{made}");
        }
        // A context something may change is not proven to hold React's
        // `Provider`; React's context readers change nothing.
        let read = "import { useContext } from 'react';\nimport { Shared } from './contexts';\n\
                    export const useShared = () => useContext(Shared);\n";
        for (more, want) in [
            ("export const useOwn = () => useContext(Shared);\n", &[][..]),
            ("Shared.Provider = pick();\n", &["p"][..]),
            ("Shared['Provider'] = pick();\n", &["p"][..]),
            ("delete Shared.Provider;\nrestore(Shared);\n", &["p"][..]),
            ("consume(Shared);\n", &["p"][..]),
        ] {
            let contexts = format!("import {{ createContext, useContext }} from 'react';\nexport const Shared = createContext(null);\n{more}");
            let app = "import { Box } from './kit';\nimport { Shared } from './contexts';\n\
                       export const App = () => <Shared.Provider value={1}><Box p={8} /></Shared.Provider>;\n";
            let files = [("kit.tsx", kit), ("contexts.tsx", contexts.as_str()), ("read.tsx", read), ("app.tsx", app)];
            assert_eq!(analyze(&files, &test_inputs()).dynamic_props.keys().collect::<Vec<_>>(), want, "{more}");
        }
        // Nor is one an opening may reach: code run from a string, a hand-on
        // of its module's namespace, a runtime load of it, or a write through
        // the namespace of a module the analysis cannot find or does not read,
        // which may re-export it.
        let app = "import { Box } from './kit';\nimport { Shared } from './contexts';\n\
                   export const App = () => <Shared.Provider value={1}><Box p={8} /></Shared.Provider>;\n";
        for (other, want) in [
            ("export const make = (source) => new Function(source);\n", &["p"][..]),
            ("import * as contexts from './contexts';\nconsume(contexts);\n", &["p"][..]),
            ("export * as contexts from './contexts';\n", &["p"][..]),
            ("import('./contexts').then(consume);\n", &["p"][..]),
            ("import * as lib from './missing';\nlib.Shared.Provider = pick();\n", &["p"][..]),
            ("import * as ui from '@local/proxy';\nui.Shared.Provider = pick();\n", &["p"][..]),
            ("export const other = 1;\n", &[][..]),
        ] {
            let files = [("kit.tsx", kit), ("contexts.tsx", contexts), ("other.ts", other), ("app.tsx", app)];
            assert_eq!(analyze(&files, &test_inputs()).dynamic_props.keys().collect::<Vec<_>>(), want, "{other}");
        }
        // A use reaches the context however it is named: through a namespace
        // member path, a renamed re-export, a star, a default that holds it or
        // a local alias.
        let renamed = "export { Shared as Renamed } from './contexts';\n";
        let star = "export * from './contexts';\n";
        let default = "import { Shared } from './contexts';\nexport default Shared;\n";
        for (barrel, other) in [
            ("", "import * as contexts from './contexts';\ncontexts.Shared.Provider = pick();\n"),
            ("", "import * as contexts from './contexts';\ndelete contexts.Shared.Provider;\n"),
            ("", "import * as contexts from './contexts';\nconsume(contexts.Shared);\n"),
            (renamed, "import * as b from './barrel';\nb.Renamed.Provider = pick();\n"),
            (star, "import * as b from './barrel';\nb.Shared.Provider = pick();\n"),
            (default, "import D from './barrel';\nD.Provider = pick();\n"),
            (default, "import * as b from './barrel';\nb.default.Provider = pick();\n"),
            ("", "import { Shared } from './contexts';\nconst Alias = Shared;\nAlias.Provider = pick();\n"),
        ] {
            let files =
                [("kit.tsx", kit), ("contexts.tsx", contexts), ("barrel.ts", barrel), ("other.ts", other), ("app.tsx", app)];
            assert_eq!(analyze(&files, &test_inputs()).dynamic_props.keys().collect::<Vec<_>>(), ["p"], "{barrel}{other}");
        }
        // A context's members are not known, so a facade that spreads one
        // may hold any member: `<Parts.Root>` stays uncertain.
        let parts = "import { createContext } from 'react';\nexport const Shared = createContext(null);\n\
                     export const Root = ds.styles({ padding: 4 })\n\
                       .variant({ prop: 'size', defaultVariant: 'sm', variants: { sm: { margin: 1 }, lg: { margin: 9 } } })\n\
                       .asElement('div');\n\
                     export const Parts = { Root, ...Shared };\n";
        let app = "import { Box } from './kit';\nimport { Parts, Shared } from './parts';\n\
                   export const App = () => <Shared.Provider value={1}><Parts.Root size='sm' /><Box p={8} /></Shared.Provider>;\n";
        let files = [("kit.tsx", kit), ("contexts.tsx", contexts), ("parts.tsx", parts), ("app.tsx", app)];
        assert_eq!(analyze(&files, &test_inputs()).dynamic_props.keys().collect::<Vec<_>>(), ["p"]);
    }

    /// A tag whose type a function's own prop chooses (`createElement(as ??
    /// 'label', …)` in `function Root({ as })`) renders a host element when
    /// every route by which the analysis sees the function render is read
    /// and gives the prop a string or leaves it out: a component
    /// `.asComponent()` builds from it, or an object member's JSX tag. Then
    /// it leaves usage proven. A runtime value, a spread, the object or the
    /// function as a value, or no analysed route at all keeps it blocking.
    #[test]
    fn props_that_choose_a_host_element_leave_usage_proven() {
        let kit = "export const Box = ds.system({ space: true }).asElement('div');\n\
                   export const Base = ds.styles({ display: 'block' }).asElement('div');\n";
        let el = "import { createElement } from 'react';\n\
                  export function El({ as, ...props }) { if (as) return createElement(as, props); return <label {...props} />; }\n\
                  export function Root({ as, children }) { return createElement(as ?? 'label', {}, children); }\n\
                  export const Parts = { Root };\n";
        let outer = "import { Base } from './kit';\nimport { El } from './el';\nexport const Outer = Base.extend().asComponent(El);\n";
        let both = "() => <><Outer /><Parts.Root /><Box p={8} /></>";
        let barrel = |source| [("barrel.ts", source)];
        let f = [("f.tsx", "import { createElement } from 'react';\nexport function F({ as }) { return createElement(as ?? 'span', {}); }\n")];
        let host = ("h.tsx", "import { createElement } from 'react';\nexport function H({ as, ...props }) { return createElement(as ?? 'span', props); }\n");
        let h_star_as = [host, ("barrel.ts", "export * as ns from './h';\n")];
        let h_import_export = [host, ("barrel.ts", "import * as ns from './h';\nexport { ns };\n")];
        let h_default = [host, ("barrel.ts", "import * as ns from './h';\nexport default ns;\n")];
        let h_type_only = [host, ("barrel.ts", "import type * as ns from './h';\nexport type { ns };\n")];
        let h_type_export = [host, ("barrel.ts", "import * as ns from './h';\nexport type { ns };\n")];
        // The function module's additions, the app, any further files and the
        // slots left.
        type Case<'a> = (&'a str, &'a str, &'a [(&'a str, &'a str)], &'a [&'a str]);
        let cases: [Case; 25] = [
            ("", "() => <><Outer /><Parts.Root><div /></Parts.Root><Box p={8} /></>", &[], &[]),
            ("", "() => <><Outer as=\"span\" /><Parts.Root as=\"section\" /><Box p={8} /></>", &[], &[]),
            ("", "({ X }) => <><Outer as={X} /><Box p={8} /></>", &[], &["p"]),
            ("", "({ r }) => <><Outer {...r} /><Box p={8} /></>", &[], &["p"]),
            ("", "({ X }) => <><Parts.Root as={X} /><Box p={8} /></>", &[], &["p"]),
            ("", "() => <><Outer /><Box p={8} /></>;\nexport const all = Object.values(Parts)", &[], &["p"]),
            ("", "({ X }) => <><El as={X} /><Box p={8} /></>", &[], &["p"]),
            ("export const list = [El];\n", both, &[], &["p"]),
            // Nothing analysed renders `Alone`, or `Root` through its holder,
            // or `El` through an outer: code outside may, with any `as`.
            ("export function Alone({ as }) { return createElement(as ?? 'label', {}); }\n", both, &[], &["p"]),
            ("", "() => <><Outer /><Box p={8} /></>", &[], &["p"]),
            ("", "() => <><Parts.Root /><Box p={8} /></>", &[], &["p"]),
            // An omitted prop whose default is not a host element's name.
            ("export function Dflt({ as = globalThis.Tag, children }) { return createElement(as, {}, children); }\n",
             "() => <Dflt><Box p={8} /></Dflt>;\nimport { Dflt } from './el'", &[], &["p"]),
            // An element handed to code outside, which may clone it.
            ("", "() => <><Outer /><Parts.Root /><Box p={8} /></>;\nconsume(() => <El as=\"div\" />)", &[], &["p"]),
            // A module loaded at runtime, directly or through a barrel.
            ("", "() => <><Outer /><Parts.Root /><F /><Box p={8} /></>;\nimport { F } from './f'", &f, &[]),
            ("", "() => <><Outer /><Parts.Root /><F /><Box p={8} /></>;\nimport { F } from './f';\nimport('./f').then(consume)", &f, &["p"]),
            ("", "() => <><Outer /><Parts.Root /><F /><Box p={8} /></>;\nimport { F } from './f';\nconsume(require('./f'))", &f, &["p"]),
            ("", "() => <><Outer /><Parts.Root /><Box p={8} /></>;\nimport('./barrel').then(consume)", &barrel("export { El } from './el';\n"), &["p"]),
            ("", "() => <><Outer /><Parts.Root /><Box p={8} /></>;\nimport('./barrel').then(consume)", &barrel("import { El } from './el';\nexport { El };\n"), &["p"]),
            // A namespace re-exported, however spelled.
            ("", "() => <><Outer /><Parts.Root /><H /><Box p={8} /></>;\nimport { H } from './h';\nimport('./barrel').then(consume)", &h_star_as, &["p"]),
            ("", "() => <><Outer /><Parts.Root /><H /><Box p={8} /></>;\nimport { H } from './h';\nimport('./barrel').then(consume)", &h_import_export, &["p"]),
            ("", "() => <><Outer /><Parts.Root /><H /><Box p={8} /></>;\nimport { H } from './h';\nimport('./barrel').then(consume)", &h_default, &["p"]),
            // A type-only namespace export is erased: it exports nothing.
            ("", "() => <><Outer /><Parts.Root /><H /><Box p={8} /></>;\nimport { H } from './h';\nimport('./barrel').then(consume)", &h_type_only, &[]),
            ("", "() => <><Outer /><Parts.Root /><H /><Box p={8} /></>;\nimport { H } from './h';\nimport('./barrel').then(consume)", &h_type_export, &[]),
            // A default export, however spelled.
            ("export { El as default };\n", both, &[], &["p"]),
            ("", both, &barrel("export { El as default } from './el';\n"), &["p"]),
        ];
        for (more, app, extra, want) in cases {
            let el = format!("{el}{more}");
            let app = format!(
                "import {{ Box }} from './kit';\nimport {{ Outer }} from './outer';\nimport {{ Parts, El }} from './el';\n\
                 export const App = {app};\n"
            );
            let mut files = vec![("kit.tsx", kit), ("el.tsx", el.as_str()), ("outer.tsx", outer), ("app.tsx", app.as_str())];
            files.extend(extra);
            assert_eq!(analyze(&files, &test_inputs()).dynamic_props.keys().collect::<Vec<_>>(), want, "{more}{app}");
        }
    }

    /// A `createElement` props object usage reads in full writes what it
    /// lists, as JSX attributes do, and no longer opens its component; one
    /// that spreads a rest parameter may write anything but the keys that
    /// rest leaves out. Any other props argument, or a rest something may
    /// add to, keeps the component open.
    #[test]
    fn create_element_props_read_in_full_confine_their_component() {
        let kit = "export const Box = ds.system({ space: true }).asElement('div');\n\
                   export const Base = ds.styles({ display: 'block' }).asElement('div');\n";
        let cases: [(&str, &[&str]); 5] = [
            ("export const App = () => createElement(Box, { p: 8 });", &[]),
            ("export const App = ({ n }) => createElement(Box, { p: n });", &["p"]),
            ("export const App = ({ props }) => createElement(Box, props);", &["p"]),
            // The wrapper is followed, as its JSX is: `p` is the literal its render passes.
            ("function F({ as, ...rest }) { return createElement(Box, { ...rest, id: 'x' }); }\nexport const App = () => <F p={8} />;", &[]),
            ("function F({ as, ...rest }) { rest.p = 1; return createElement(Box, { ...rest }); }\nexport const App = () => <F />;", &["p"]),
        ];
        for (app, want) in cases {
            let app = format!("import {{ Box }} from './kit';\nimport {{ createElement }} from 'react';\n{app}\n");
            let out = analyze(&[("kit.tsx", kit), ("app.tsx", app.as_str())], &test_inputs());
            assert_eq!(out.dynamic_props.keys().collect::<Vec<_>>(), want, "{app}");
        }
        // A rest that took `as` out cannot hand an `.asComponent()` target
        // the `as` that chooses its element.
        let el = |reads: &str| {
            format!(
                "import {{ createElement }} from 'react';\nimport {{ Base }} from './kit';\n\
                 function El({{ as, ...props }}) {{ if (as) return createElement(as, props); return <label {{...props}} />; }}\n\
                 export const Outer = Base.extend().asComponent(El);\n\
                 function Root({{ as, asChild, ...props }}) {{ {reads}return createElement(Outer, {{ ...props, asChild: true }}); }}\n\
                 export const Parts = {{ Root }};\n"
            )
        };
        let rendered = "() => <><Parts.Root as=\"div\" /><Box p={8} /></>";
        for (reads, app, want) in [
            ("", rendered, &[][..]),
            ("", "({ X }) => <><Outer as={X} /><Parts.Root /><Box p={8} /></>", &["p"][..]),
            ("const id = props.id;\n", rendered, &[][..]),
            // A call through a member, however wrapped, or an iterating
            // spread runs code with the rest as its receiver, which may write
            // `as` into it.
            ("(props.mutate)();\n", rendered, &["p"][..]),
            ("(props.mutate as any)();\n", rendered, &["p"][..]),
            ("props.mutate!();\n", rendered, &["p"][..]),
            ("props.mutate``;\n", rendered, &["p"][..]),
            ("[...props];\n", rendered, &["p"][..]),
            ("consume(...props);\n", rendered, &["p"][..]),
        ] {
            let el = el(reads);
            let app = format!("import {{ Box }} from './kit';\nimport {{ Parts, Outer }} from './el';\nexport const App = {app};\n");
            let out = analyze(&[("kit.tsx", kit), ("el.tsx", el.as_str()), ("app.tsx", app.as_str())], &test_inputs());
            assert_eq!(out.dynamic_props.keys().collect::<Vec<_>>(), want, "{reads}{app}");
        }
    }

    /// A component object some module writes a member of, or hands on, may
    /// render through code usage cannot see, so the elements it receives
    /// keep their floor.
    #[test]
    fn mutated_component_objects_lose_receiver_trust() {
        let kit = "export const Box = ds.system({ space: true }).asElement('div');\n\
                   export const R = ds.styles({ display: 'block' }).asElement('div');\n";
        let render = "import { Box, R } from './kit';\nexport const App = () => <R><Box p={8} /></R>;\n";
        let cases: [(&str, &str, &[&str]); 5] = [
            ("", "", &[]),
            ("R.render = globalThis.Slot;\n", "", &["p"]),
            ("", "import { R } from './kit';\nR.render = globalThis.Slot;\n", &["p"]),
            ("", "import * as kit from './kit';\nkit.R.render = globalThis.Slot;\n", &["p"]),
            ("", "import { R } from './kit';\nconsume(R);\n", &["p"]),
        ];
        for (in_kit, other, want) in cases {
            let kit = format!("{kit}{in_kit}");
            let mut files = vec![("kit.tsx", kit.as_str()), ("app.tsx", render)];
            if !other.is_empty() {
                files.push(("other.tsx", other));
            }
            assert_eq!(analyze(&files, &test_inputs()).dynamic_props.keys().collect::<Vec<_>>(), want, "{in_kit}{other}");
        }
    }

    #[test]
    fn identical_definitions_share_a_slot_under_any_binding() {
        let copy = |binding: &str| {
            format!("export const {binding} = ds.props({{ tone: {{ property: 'color' }} }}).asElement('span');\n")
        };
        let (text, span) = (copy("Text"), copy("Span"));
        let other = "export const Span = ds.props({ tone: { property: 'fill' } }).asElement('span');\n";
        let app = "import { Text } from './text';\nimport { Span } from './span';\nimport { Span as Other } from './other';\n\
                   export const App = ({ n }) => <><Text tone={`${n}`} /><Span tone={`${n}`} /><Other tone={`${n}`} /></>;\n";
        let registered = |files: &[(&str, &str)]| {
            let out = analyze(files, &test_inputs());
            out.sheets.global.lines().filter(|line| line.starts_with("@property --animus-tone_")).map(str::to_string).collect::<Vec<_>>()
        };
        let forward = registered(&[("text.tsx", &text), ("span.tsx", &span), ("other.tsx", other), ("app.tsx", app)]);
        let backward = registered(&[("app.tsx", app), ("other.tsx", other), ("span.tsx", &span), ("text.tsx", &text)]);
        assert_eq!(forward.len(), 2, "copies share one registration, the other definition keeps its own: {forward:?}");
        assert_eq!(forward, backward, "names follow no file order");
        // Development names each component's props by its own binding, an
        // installed kit's too, as before copies shared.
        let mut development = test_inputs();
        development.dev_mode = true;
        let installed = "import { Text } from '../node_modules/kit-a/text';\nimport { Span } from '../node_modules/kit-b/span';\n\
                         export const App = ({ n }) => <><Text tone={`${n}`} /><Span tone={`${n}`} /></>;\n";
        let out = analyze(
            &[("node_modules/kit-a/text.tsx", &text), ("node_modules/kit-b/span.tsx", &span), ("src/app.tsx", installed)],
            &development,
        );
        let names: Vec<_> = ["tone_Text_", "tone_Span_"]
            .iter()
            .map(|name| out.sheets.global.lines().any(|line| line.starts_with(&format!("@property --animus-{name}"))))
            .collect();
        assert_eq!(names, [true, true], "{}", out.sheets.global);
    }

    #[test]
    fn slots_serve_only_the_conditions_known_value_shapes_write() {
        let kit = "export const Box = ds.system({ space: true }).props({ tone: { property: 'color' } }).asElement('div');\n";
        // The slot rules and registered variables each render emits.
        let slots = |app: &str, inputs: &CssInputs| {
            let app = format!("import {{ Box }} from './kit';\n{app}");
            let out = analyze(&[("kit.tsx", kit), ("app.tsx", &app)], inputs);
            let css = format!("{}{}", out.sheets.system, out.sheets.custom);
            let mut rules: Vec<String> = css
                .split(".animus-dyn-")
                .skip(1)
                .map(|rule| rule.split([' ', '{']).next().unwrap().to_string())
                .collect();
            rules.dedup();
            let registered = out.sheets.global.lines().filter(|line| line.starts_with("@property --animus-")).count();
            assert_eq!(registered, rules.len(), "{app}");
            rules
        };
        let cases: [(&str, &[&str]); 7] = [
            // A scalar writes the base; an object literal, its keys.
            ("export const App = ({ n }) => <Box p={`${n}px`} />;\n", &["p_"]),
            ("export const App = ({ c, n }) => <Box p={c ? 8 : `${n}px`} />;\n", &["p_"]),
            ("export const App = ({ n, m }) => <Box p={{ _: n, sm: m }} />;\n", &["p_", "p_-sm"]),
            ("export const App = ({ n }) => <Box tone={{ sm: n }} />;\n", &["tone_Box_091638e9-sm"]),
            // A value of unknown shape, or a spread, may write any condition.
            ("export const App = ({ c, n }) => <Box p={c ? 8 : n} />;\n", &["p_", "p_-sm"]),
            ("export const App = ({ n, ...rest }) => <Box {...rest} p={`${n}`} />;\n", &["p_", "p_-sm", "tone_Box_091638e9", "tone_Box_091638e9-sm"]),
            // So may a clone's override, whatever the element writes.
            ("import { cloneElement } from 'react';\nfunction Wrap({ children, n }) { return cloneElement(children, { p: n }); }\nexport const App = ({ m, n }) => <Wrap n={n}><Box p={`${m}px`} /></Wrap>;\n", &["p_", "p_-sm"]),
        ];
        for (app, want) in cases {
            assert_eq!(slots(app, &test_inputs()), want, "{app}");
        }
        // A component staticCss forces renders with values in any shape.
        let mut forced = test_inputs();
        forced.static_css =
            Some(crate::forced_usage::StaticCssConfig::parse(r#"{"components":{"Box":{"dynamicProps":["tone"]}}}"#).unwrap());
        let app = "export const App = ({ n }) => <Box tone={`${n}`} />;\n";
        assert_eq!(slots(app, &forced), ["p_", "p_-sm", "tone_Box_091638e9", "tone_Box_091638e9-sm"]);
    }

    #[test]
    fn finite_alternatives_take_static_classes_instead_of_slots() {
        let kit = "export const Box = ds.system({ space: true }).props({ tone: { property: 'color' } }).asElement('div');\n";
        // The `p` and `tone` class keys, and the slot rules, each render emits.
        let emitted = |app: &str| {
            let app = format!("import {{ Box }} from './kit';\n{app}");
            let out = analyze(&[("kit.tsx", kit), ("app.tsx", &app)], &test_inputs());
            let css = format!("{}{}", out.sheets.system, out.sheets.custom);
            let mut slots: Vec<String> = css
                .split(".animus-dyn-")
                .skip(1)
                .map(|rule| rule.split([' ', '{']).next().unwrap().to_string())
                .collect();
            slots.dedup();
            let mut keys: Vec<String> = out.system_prop_map.get("p").into_iter().flat_map(|map| map.keys().cloned()).collect();
            let tone = out.replacement_configs["kit.tsx::Box"].custom_prop_class_map.as_ref().and_then(|map| map.get("tone"));
            keys.extend(tone.into_iter().flat_map(|map| map.keys().cloned()));
            keys.sort();
            (keys, slots)
        };
        let cases: [(&str, &[&str], &[&str]); 9] = [
            // Literals, `const`s and literal-union parameters, through
            // conditionals, `||` and `??`, and object leaves at breakpoints.
            ("const k = 20;\nexport const App = ({ c }) => <Box p={c ? k : 16} />;\n", &["16", "20"], &[]),
            ("export const App = ({ c }: { c?: 4 | 0 }) => <Box p={c || 8} />;\n", &["4", "8"], &[]),
            ("type S = 4 | 8;\ninterface P { s?: S }\nexport const App = ({ s = 2 }: P) => <Box p={s} />;\n", &["2", "4", "8"], &[]),
            ("export function App(t: 'red' | 'blue') { return <Box tone={t} />; }\n", &["blue", "red"], &[]),
            ("export const App = ({ c }) => <Box p={{ _: c ? 4 : 8, sm: 16 }} />;\n", &["4", "8", "sm:16"], &[]),
            // A wide, opaque or reassigned value keeps its slot.
            ("export const App = ({ c, n }) => <Box p={c ? 8 : n} />;\n", &[], &["p_", "p_-sm"]),
            ("export const App = ({ s }: { s: number }) => <Box p={s} />;\n", &[], &["p_", "p_-sm"]),
            ("export const App = ({ s }: { s: 4 | 8 }) => { s = 3; return <Box p={s} />; };\n", &[], &["p_", "p_-sm"]),
            ("const sizes = { sm: 4 };\nexport const App = ({ c }) => <Box p={c ? sizes.sm : 8} />;\n", &["4", "8"], &["p_", "p_-sm"]),
        ];
        for (app, classes, slots) in cases {
            assert_eq!(emitted(app), (classes.iter().map(|key| key.to_string()).collect(), slots.iter().map(|slot| slot.to_string()).collect()), "{app}");
        }
    }

    #[test]
    fn component_callback_lookups_keep_the_authored_value_type() {
        let source = r#"export const Box = ds
  .props({
    tp: { property: 'width', transform: (v) => (typeof v === 'number' ? `${v}px` : `${v}%`) },
    plain: { property: 'height' },
  })
  .asElement('div');
export const App = () => (
  <><Box tp={100} plain={5} /><Box tp="100" /><Box tp={{ _: 100, sm: '100' }} /></>
);
"#;
        let out = analyze(&[("a.tsx", source)], &test_inputs());
        let classes = custom_classes(&out, "a.tsx::Box", "tp");
        let mut keys: Vec<&String> = classes.keys().collect();
        keys.sort();
        assert_eq!(keys, ["\"100\"", "100", "{\"_\":100,\"sm\":\"100\"}"]);
        assert_ne!(classes["100"], classes["\"100\""]);
        assert!(out.sheets.custom.contains("width: 100px;"), "{}", out.sheets.custom);
        assert!(out.sheets.custom.contains("width: 100%;"), "{}", out.sheets.custom);
        // A prop without a callback keeps the shared value keys.
        assert_eq!(custom_classes(&out, "a.tsx::Box", "plain").keys().collect::<Vec<_>>(), ["5"]);
        assert_eq!(out.replacement_configs["a.tsx::Box"].typed_custom_props, ["tp"]);
    }

    #[test]
    fn a_binding_evaluates_the_callback_the_runtime_selects() {
        // JS keeps the last of a repeated key, and a later `.props()`
        // replaces the prop: each binding evaluates that callback, whatever
        // the replaced one compiles to (C's reads an import).
        let source = r#"import { k } from './k';
export const A = ds.props({ w: { property: 'width', transform: (v) => `${v * 2}px` }, w: { property: 'width', transform: (v) => `${v * 3}px` } }).asElement('div');
export const B = ds.props({ w: { property: 'height', transform: (v) => `${v * 2}px`, transform: (v) => `${v * 3}px` } }).asElement('div');
export const C = ds.props({ w: { property: 'minWidth', transform: (v) => `${v * k}px` }, w: { property: 'minWidth', transform: (v) => `${v * 3}px` } }).asElement('div');
export const D = ds.props({ w: { property: 'maxWidth', transform: (v) => `${v * 2}px` } }).props({ w: { property: 'maxWidth', transform: (v) => `${v * 3}px` } }).asElement('div');
export const App = () => <><A w={5} /><B w={5} /><C w={5} /><D w={5} /></>;
"#;
        let out = analyze(&[("a.tsx", source), ("k.ts", "export const k = 2;\n")], &test_inputs());
        let selected: Vec<bool> = ["width", "height", "min-width", "max-width"]
            .iter()
            .map(|property| out.sheets.custom.contains(&format!("{property}: 15px;")))
            .collect();
        assert_eq!(selected, [true; 4], "{}", out.sheets.custom);
        assert!(!out.sheets.custom.contains(": 10px;"), "{}", out.sheets.custom);
    }

    #[test]
    fn unbounded_host_sensitive_or_mutating_callbacks_keep_their_runtime_path() {
        let declare = |props: &str, renders: &str| {
            format!(
                "export const Box = ds.props({{ {props} }}).asElement('div');\nexport const S = ds.styles({{ w: 2.6 }}).asElement('span');\nexport const App = () => <><S />{renders}</>;\n"
            )
        };
        let spin = "spin: { property: 'minWidth', transform: (v) => { while (v > 0) { v = v + 1; } return v; } }";
        let host = "host: { property: 'minHeight', transform: (v) => (typeof globalThis.window === 'undefined' ? `${v}px` : `${v * 2}px`) }";
        let fin = "fin: { property: 'maxWidth', transform: (v) => v * 2 }";
        let mutate = "ma: { property: 'paddingTop', transform: (v) => { Math.round = () => 7; return `${v}px`; } }";
        let reads = "mb: { property: 'paddingLeft', transform: (v) => `${Math.round(v)}px` }";
        let mut inputs = test_inputs();
        inputs.config.insert(
            "w".into(),
            serde_json::from_str(r#"{"property": "width", "transform": "round", "transformId": "round@system.w"}"#)
                .unwrap(),
        );
        inputs
            .set_transform_sources(Some(r#"{"round@system.w": "(v) => `${Math.round(v)}px`"}"#))
            .unwrap();
        for (props, renders) in [
            (
                [spin, host, fin, mutate, reads].join(", "),
                "<Box spin={1} host={3} fin={10} ma={1} mb={2.4} />",
            ),
            (
                [reads, mutate, fin, host, spin].join(", "),
                "<Box mb={2.4} ma={1} fin={10} host={3} spin={1} />",
            ),
        ] {
            let started = std::time::Instant::now();
            let out = analyze(&[("a.tsx", &declare(&props, renders))], &inputs);
            assert!(started.elapsed() < std::time::Duration::from_secs(10));
            let custom = &out.sheets.custom;
            assert!(custom_classes(&out, "a.tsx::Box", "spin").is_empty(), "{custom}");
            assert!(custom_classes(&out, "a.tsx::Box", "host").is_empty(), "{custom}");
            assert!(custom.contains("max-width: 20;"), "{custom}");
            assert!(custom.contains("padding-left: 2px;"), "{custom}");
            assert!(out.css.contains("width: 3px;"), "{}", out.css);
            let dynamic = out.replacement_configs["a.tsx::Box"].custom_dynamic_config.as_ref().unwrap();
            assert!(dynamic.contains_key("spin") && dynamic.contains_key("host"));
            assert!(out.diagnostics.iter().all(|d| d.component != "Box"), "{:?}", out.diagnostics);
        }
    }

    #[test]
    fn component_callback_failures_name_the_declaring_component() {
        let parents = r#"export const Parent = ds
  .props({
    w: { property: 'width', transform: (v) => { if (v === 7) throw new Error('seven'); return `${v}px`; } },
    o: { property: 'height', transform: (v) => ({ v }) },
  })
  .asElement('div');
"#;
        let children = r#"import { Parent } from './parents';
export const Child = Parent.extend().styles({ display: 'grid' }).asElement('div');
export const Grand = Child.extend().styles({ display: 'flex' }).asElement('div');
export const Override = Parent.extend()
  .props({ w: { property: 'width', transform: (v) => { if (v === 7) throw new Error('mine'); return v; } } })
  .asElement('div');
export const App = () => <><Child w={7} o={3} /><Grand w={7} o={3} /><Override w={7} /></>;
"#;
        let out = analyze(&[("parents.tsx", parents), ("children.tsx", children)], &test_inputs());
        let of = |kind: &str| -> Vec<(&str, &str)> {
            out.diagnostics
                .iter()
                .filter(|d| d.kind == kind && d.message.contains("transform 'inline'"))
                .map(|d| (d.file.as_str(), d.component.as_str()))
                .collect()
        };
        assert_eq!(of("warn"), [("parents.tsx", "Parent"), ("children.tsx", "Override")], "{:?}", out.diagnostics);
        assert_eq!(of("error"), [("parents.tsx", "Parent")], "{:?}", out.diagnostics);
    }

    #[test]
